export const snippets = {
    "types/primitives": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Destack has fixed-width numeric primitives in addition to TypeScript-shaped values.</span>\n<span data-k=\"comment\">* Literal bounds are checked statically when the target type is known.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"comment\">// integers can use exact widths</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">flag</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint3</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">7</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">byte</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint8</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">255</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">offset</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int17</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">-</span><span data-k=\"literal\">32768</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">index</span><span data-k=\"punct\">:</span> <span data-k=\"type\">usize</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1024</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// floats keep explicit target precision</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">ratio</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0.5</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">total</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">100.25</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">total</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">float64</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// strings and chars stay TypeScript-shaped</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">initial</span><span data-k=\"punct\">:</span> <span data-k=\"type\">char</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">'D'</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;destack&quot;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">readInput</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">unknown</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">abort</span><span data-k=\"punct\">(</span><span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">never</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// unknown must be narrowed before useful access</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">input</span><span data-k=\"punct\">:</span> <span data-k=\"type\">unknown</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">readInput</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// `never` represents code that does not continue</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">fail</span><span data-k=\"punct\">(</span><span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">never</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">abort</span><span data-k=\"punct\">(</span><span data-k=\"name\">message</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Destack has fixed-width numeric primitives in addition to TypeScript-shaped values.\n* Literal bounds are checked statically when the target type is known.\n*/\n\n// integers can use exact widths\nconst flag: uint3 = 7;\nconst byte: uint8 = 255;\nconst offset: int17 = -32768;\nconst index: usize = 1024;\n\n// floats keep explicit target precision\nconst ratio: float32 = 0.5;\nconst total: float = 100.25;\ntotal satisfies float64;\n\n// strings and chars stay TypeScript-shaped\nconst initial: char = 'D';\nconst name: string = \"destack\";\n\ndeclare function readInput(): unknown;\ndeclare function abort(message: string): never;\n\n// unknown must be narrowed before useful access\nconst input: unknown = readInput();\n\n// `never` represents code that does not continue\nfunction fail(message: string): never {\n    abort(message)\n}\n"
    },
    "types/intervals": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Ranges in type position define static interval types.</span>\n<span data-k=\"comment\">* Intervals work for bounded scalar types like integers and chars.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">Digit</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">9</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">LowerAscii</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">'a'</span><span data-k=\"punct\">..=</span><span data-k=\"string\">'z'</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">UserPort</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1024</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">65535</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">HexDigit</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Digit</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">'a'</span><span data-k=\"punct\">..=</span><span data-k=\"string\">'f'</span><span data-k=\"punct\">;</span>\n\nnewtype <span data-k=\"type\">Port</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">UserPort</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// interval bounds can constrain comptime values</span>\nstruct <span data-k=\"type\">InlineBuffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> comptime <span data-k=\"type\">Size</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">4096</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">storage</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"type\">Size</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// valid literals inherit the scalar base type</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">digit</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Digit</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">7</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">letter</span><span data-k=\"punct\">:</span> <span data-k=\"type\">LowerAscii</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">'m'</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">port</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Port</span><span data-k=\"punct\">(</span><span data-k=\"literal\">8080</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// invalid literals fail before runtime</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">invalid</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserPort</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">70000</span><span data-k=\"punct\">;</span>\n                          <span data-k=\"inline-diagnostic-shadow\"><span data-k=\"inline-diagnostic-box\"><span data-k=\"squiggle\">~~~~~</span>\n<span data-k=\"message\">error: value is outside 1024..=65535</span></span></span>\n\n<span data-k=\"name\">digit</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">int</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">letter</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">char</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">port</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Port</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Ranges in type position define static interval types.\n* Intervals work for bounded scalar types like integers and chars.\n*/\n\ntype Digit = 0..=9;\ntype LowerAscii = 'a'..='z';\ntype UserPort = 1024..=65535;\ntype HexDigit = Digit | 'a'..='f';\n\nnewtype Port = UserPort;\n\n// interval bounds can constrain comptime values\nstruct InlineBuffer<T, comptime Size: 0..=4096> {\n    storage: [T; Size];\n}\n\n// valid literals inherit the scalar base type\nconst digit: Digit = 7;\nconst letter: LowerAscii = 'm';\nconst port = Port(8080);\n\n// invalid literals fail before runtime\nconst invalid: UserPort = 70000;\n                          ~~~~~\n                          error: value is outside 1024..=65535\n\ndigit satisfies int;\nletter satisfies char;\nport satisfies Port;\n"
    },
    "types/newtypes": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* `newtype` adds nominal identity around a backing representation.</span>\n<span data-k=\"comment\">* Backing values do not satisfy the new type by accident.</span>\n<span data-k=\"comment\">*/</span>\n\nnewtype <span data-k=\"type\">UserId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span>\nnewtype <span data-k=\"type\">Email</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// raw backing values do not pass as nominal ids</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">invalid</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">42</span><span data-k=\"punct\">;</span>\n                        <span data-k=\"inline-diagnostic-shadow\"><span data-k=\"inline-diagnostic-box\"><span data-k=\"squiggle\">~~</span>\n<span data-k=\"message\">error: expected UserId, found uint64</span></span></span>\n\n<span data-k=\"comment\">// construction is explicit at the boundary</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">userId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">(</span><span data-k=\"literal\">42</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">email</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Email</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;ada@destack.sh&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">userId</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">email</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Email</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* `newtype` adds nominal identity around a backing representation.\n* Backing values do not satisfy the new type by accident.\n*/\n\nnewtype UserId = uint64;\nnewtype Email = string;\n\n// raw backing values do not pass as nominal ids\nconst invalid: UserId = 42;\n                        ~~\n                        error: expected UserId, found uint64\n\n// construction is explicit at the boundary\nconst userId = UserId(42);\nconst email = Email(\"ada@destack.sh\");\n\nuserId satisfies UserId;\nemail satisfies Email;\n"
    },
    "types/extensions": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Extensions attach logic to a type without changing its stored shape.</span>\n<span data-k=\"comment\">* Extensions in the same file are visible wherever the type is used.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">class</span> <span data-k=\"type\">Vector2</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">constructor</span><span data-k=\"punct\">(</span><span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        this<span data-k=\"punct\">.</span><span data-k=\"name\">x</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">x</span><span data-k=\"punct\">;</span>\n        this<span data-k=\"punct\">.</span><span data-k=\"name\">y</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">y</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// methods and statics attach outside the stored shape</span>\nextension <span data-k=\"keyword\">of</span> <span data-k=\"type\">Vector2</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">static</span> <span data-k=\"name\">ZERO</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Vector2</span><span data-k=\"punct\">(</span><span data-k=\"literal\">0.0</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0.0</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">magnitude</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"punct\">(</span>this<span data-k=\"punct\">.</span><span data-k=\"name\">x</span> <span data-k=\"punct\">*</span> this<span data-k=\"punct\">.</span><span data-k=\"name\">x</span> <span data-k=\"punct\">+</span> this<span data-k=\"punct\">.</span><span data-k=\"name\">y</span> <span data-k=\"punct\">*</span> this<span data-k=\"punct\">.</span><span data-k=\"name\">y</span><span data-k=\"punct\">)</span><span data-k=\"punct\">.</span><span data-k=\"name\">sqrt</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// extension members read as ordinary members</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">origin</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Vector2</span><span data-k=\"punct\">.</span><span data-k=\"name\">ZERO</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">origin</span><span data-k=\"punct\">.</span><span data-k=\"name\">magnitude</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Extensions attach logic to a type without changing its stored shape.\n* Extensions in the same file are visible wherever the type is used.\n*/\n\nclass Vector2 {\n    x: float32;\n    y: float32;\n\n    constructor(x: float32, y: float32) {\n        this.x = x;\n        this.y = y;\n    }\n}\n\n// methods and statics attach outside the stored shape\nextension of Vector2 {\n    static ZERO = new Vector2(0.0, 0.0);\n\n    magnitude(): float32 {\n        (this.x * this.x + this.y * this.y).sqrt()\n    }\n}\n\n// extension members read as ordinary members\nconst origin = Vector2.ZERO;\norigin.magnitude() satisfies float32;\n"
    },
    "types/enums": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Enums are nominal discriminants with attached constants and methods.</span>\n<span data-k=\"comment\">* The underlying representation is still a compact scalar value.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">enum</span> <span data-k=\"type\">Priority</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">Low</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">,</span>\n    <span data-k=\"name\">Medium</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">,</span>\n    <span data-k=\"name\">High</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">,</span>\n\n    <span data-k=\"comment\">// enum declarations can carry static members</span>\n    <span data-k=\"keyword\">static</span> <span data-k=\"name\">Default</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Priority</span><span data-k=\"punct\">.</span><span data-k=\"name\">Medium</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">label</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span>\n        match <span data-k=\"punct\">(</span>this<span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n            <span data-k=\"type\">Low</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;low&quot;</span>\n            <span data-k=\"type\">Medium</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;medium&quot;</span>\n            <span data-k=\"type\">High</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;high&quot;</span>\n        <span data-k=\"punct\">}</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// enum methods preserve nominal type identity</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">priority</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Priority</span><span data-k=\"punct\">.</span><span data-k=\"name\">Default</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">priority</span><span data-k=\"punct\">.</span><span data-k=\"name\">label</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">priority</span> <span data-k=\"keyword\">as</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Enums are nominal discriminants with attached constants and methods.\n* The underlying representation is still a compact scalar value.\n*/\n\nenum Priority {\n    Low = 1,\n    Medium = 2,\n    High = 3,\n\n    // enum declarations can carry static members\n    static Default = Priority.Medium;\n\n    label(): string {\n        match (this) {\n            Low => \"low\"\n            Medium => \"medium\"\n            High => \"high\"\n        }\n    }\n}\n\n// enum methods preserve nominal type identity\nconst priority = Priority.Default;\npriority.label() satisfies string;\npriority as uint8;\n"
    },
    "types/structs": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Structs are nominal value records.</span>\n<span data-k=\"comment\">* Classes are still available when identity and methods on managed objects matter.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// classes keep managed identity and methods</span>\n<span data-k=\"keyword\">class</span> <span data-k=\"type\">Counter</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">constructor</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        this<span data-k=\"punct\">.</span><span data-k=\"name\">value</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">value</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n\n    <span data-k=\"name\">increment</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">{</span>\n        this<span data-k=\"punct\">.</span><span data-k=\"name\">value</span> <span data-k=\"punct\">+=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">;</span>\n        this<span data-k=\"punct\">.</span><span data-k=\"name\">value</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// struct literals construct nominal values</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1.0</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2.0</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">counter</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">Counter</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">counter</span><span data-k=\"punct\">.</span><span data-k=\"name\">increment</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Structs are nominal value records.\n* Classes are still available when identity and methods on managed objects matter.\n*/\n\nstruct Point {\n    x: float32;\n    y: float32;\n}\n\n// classes keep managed identity and methods\nclass Counter {\n    value: int32;\n\n    constructor(value: int32) {\n        this.value = value;\n    }\n\n    increment(): int32 {\n        this.value += 1;\n        this.value\n    }\n}\n\n// struct literals construct nominal values\nconst point = Point { x: 1.0, y: 2.0 };\nconst counter = new Counter(1);\ncounter.increment() satisfies int32;\n"
    },
    "types/tuples": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Tuples are fixed heterogeneous value containers.</span>\n<span data-k=\"comment\">* `.ds` uses parenthesized tuples instead of TypeScript array tuples.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">Cell</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"type\">uint32</span><span data-k=\"punct\">,</span> <span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"type\">boolean</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">Empty</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">One</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"type\">uint32</span><span data-k=\"punct\">,</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">cell</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Cell</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// tuple patterns bind positions by arity</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">,</span> <span data-k=\"name\">label</span><span data-k=\"punct\">,</span> <span data-k=\"name\">isActive</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">cell</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">id</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint32</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">label</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">isActive</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">boolean</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// nested tuples preserve nested element types</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">nested</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">(</span><span data-k=\"type\">uint32</span><span data-k=\"punct\">,</span> <span data-k=\"type\">uint32</span><span data-k=\"punct\">)</span><span data-k=\"punct\">,</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">(</span><span data-k=\"literal\">120</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">80</span><span data-k=\"punct\">)</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;thumbnail&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">(</span><span data-k=\"name\">width</span><span data-k=\"punct\">,</span> <span data-k=\"name\">height</span><span data-k=\"punct\">)</span><span data-k=\"punct\">,</span> <span data-k=\"name\">name</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">nested</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">width</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint32</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">height</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint32</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">name</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Tuples are fixed heterogeneous value containers.\n* `.ds` uses parenthesized tuples instead of TypeScript array tuples.\n*/\n\ntype Cell = (uint32, string, boolean);\ntype Empty = ();\ntype One = (uint32,);\n\ndeclare const cell: Cell;\n\n// tuple patterns bind positions by arity\nlet (id, label, isActive) = cell;\n\nid satisfies uint32;\nlabel satisfies string;\nisActive satisfies boolean;\n\n// nested tuples preserve nested element types\nlet nested: ((uint32, uint32), string) = ((120, 80), \"thumbnail\");\nlet ((width, height), name) = nested;\n\nwidth satisfies uint32;\nheight satisfies uint32;\nname satisfies string;\n"
    },
    "types/slices": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Slices are sized first-class views over contiguous elements.</span>\n<span data-k=\"comment\">* `[T]` is distinct from both dynamic arrays and fixed arrays.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">Image</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">pixels</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">decodeImage</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Image</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// slice patterns can bind a head and keep a slice tail</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"punct\">[</span><span data-k=\"name\">magic</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">body</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">bytes</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">magic</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">body</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// functions can accept slices without owning the backing storage</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">image</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">decodeImage</span><span data-k=\"punct\">(</span><span data-k=\"name\">body</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">image</span><span data-k=\"punct\">.</span><span data-k=\"name\">pixels</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Slices are sized first-class views over contiguous elements.\n* `[T]` is distinct from both dynamic arrays and fixed arrays.\n*/\n\nstruct Image {\n    pixels: [uint8];\n}\n\ndeclare const bytes: [uint8];\ndeclare function decodeImage(bytes: [uint8]): Image;\n\n// slice patterns can bind a head and keep a slice tail\nlet [magic, ...body] = bytes;\n\nmagic satisfies uint8;\nbody satisfies [uint8];\n\n// functions can accept slices without owning the backing storage\nconst image = decodeImage(body);\n\nimage.pixels satisfies [uint8];\n"
    },
    "types/arrays": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Fixed arrays store exactly N homogeneous elements inline.</span>\n<span data-k=\"comment\">* The length is part of the type and can come from static terms.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">Rgb</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">Block</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">4096</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">Packet</span><span data-k=\"punct\">&lt;</span>comptime <span data-k=\"type\">Size</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint32</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"type\">Size</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">color</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Rgb</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"literal\">255</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">128</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">block</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Block</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"literal\">0</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">4096</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// destructuring preserves fixed length information</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"punct\">[</span><span data-k=\"name\">red</span><span data-k=\"punct\">,</span> <span data-k=\"name\">green</span><span data-k=\"punct\">,</span> <span data-k=\"name\">blue</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">color</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">red</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">green</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">blue</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// static parameters can size inline storage</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">packet</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Packet</span><span data-k=\"punct\">&lt;</span><span data-k=\"literal\">32</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Packet</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"literal\">0</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">32</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">packet</span><span data-k=\"punct\">.</span><span data-k=\"name\">bytes</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">32</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Fixed arrays store exactly N homogeneous elements inline.\n* The length is part of the type and can come from static terms.\n*/\n\ntype Rgb = [uint8; 3];\ntype Block = [uint8; 4096];\n\nstruct Packet<comptime Size: uint32> {\n    bytes: [uint8; Size];\n}\n\nlet color: Rgb = [255, 128, 0];\nlet block: Block = [0; 4096];\n\n// destructuring preserves fixed length information\nlet [red, green, blue] = color;\n\nred satisfies uint8;\ngreen satisfies uint8;\nblue satisfies uint8;\n\n// static parameters can size inline storage\nlet packet: Packet<32> = Packet { bytes: [0; 32] };\n\npacket.bytes satisfies [uint8; 32];\n"
    },
    "types/readonly": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* In `.ds`, `readonly T` is a deep readonly view.</span>\n<span data-k=\"comment\">* Nested mutation requires a mutable view of the original value.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">Profile</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">profile</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Profile</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">tags</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">user</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// nested members inherit readonly access</span>\n<span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"name\">profile</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">Profile</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"name\">profile</span><span data-k=\"punct\">.</span><span data-k=\"name\">name</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"name\">tags</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">string</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// mutation through readonly access is rejected</span>\n<span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"name\">profile</span><span data-k=\"punct\">.</span><span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;Grace&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"inline-diagnostic-shadow\"><span data-k=\"inline-diagnostic-box\"><span data-k=\"squiggle\">~~~~~~~~~~~~~~~~~</span>\n<span data-k=\"message\">error: cannot assign through readonly User</span></span></span>\n",
        "source": "/**\n* In `.ds`, `readonly T` is a deep readonly view.\n* Nested mutation requires a mutable view of the original value.\n*/\n\nstruct Profile {\n    name: string;\n}\n\nstruct User {\n    profile: Profile;\n    tags: string[];\n}\n\ndeclare const user: readonly User;\n\n// nested members inherit readonly access\nuser.profile satisfies readonly Profile;\nuser.profile.name satisfies string;\nuser.tags satisfies readonly string[];\n\n// mutation through readonly access is rejected\nuser.profile.name = \"Grace\";\n~~~~~~~~~~~~~~~~~\nerror: cannot assign through readonly User\n"
    },
    "types/generics": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Generics can take types, variadic parameters, and comptime values.</span>\n<span data-k=\"comment\">* Value parameters participate in inference and static layout.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span>comptime <span data-k=\"type\">Size</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"type\">Size</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">Callback</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"type\">Parameters</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Return</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">parameters</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Parameters</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"type\">Return</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// comptime values become part of the instantiated type</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">copy</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> comptime <span data-k=\"type\">Size</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">source</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"type\">Size</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"type\">Size</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">let</span> <span data-k=\"name\">target</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"type\">Size</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n    <span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">let</span> <span data-k=\"name\">index</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span> <span data-k=\"name\">index</span> <span data-k=\"punct\">&lt;</span> <span data-k=\"type\">Size</span><span data-k=\"punct\">;</span> <span data-k=\"name\">index</span><span data-k=\"punct\">++</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">target</span><span data-k=\"punct\">[</span><span data-k=\"name\">index</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">source</span><span data-k=\"punct\">[</span><span data-k=\"name\">index</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n    <span data-k=\"name\">target</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// dynamic arguments can still be required to evaluate statically</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">repeat</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">,</span> comptime <span data-k=\"name\">count</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">T</span><span data-k=\"punct\">;</span> <span data-k=\"name\">count</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"punct\">[</span><span data-k=\"name\">value</span><span data-k=\"punct\">;</span> <span data-k=\"name\">count</span><span data-k=\"punct\">]</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// inference keeps literal lengths</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">rgb</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">copy</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">[</span><span data-k=\"literal\">255</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">128</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">names</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">repeat</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;destack&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">rgb</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"literal\">3</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">names</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">[</span><span data-k=\"type\">string</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">2</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Generics can take types, variadic parameters, and comptime values.\n* Value parameters participate in inference and static layout.\n*/\n\ntype Buffer<comptime Size: uint> = [uint8; Size];\ntype Callback<...Parameters, Return> = (...parameters: Parameters) => Return;\n\n// comptime values become part of the instantiated type\nfunction copy<T, comptime Size: uint>(source: [T; Size]): [T; Size] {\n    let target: [T; Size];\n    for (let index = 0; index < Size; index++) {\n        target[index] = source[index];\n    }\n    target\n}\n\n// dynamic arguments can still be required to evaluate statically\nfunction repeat<T>(value: T, comptime count: uint): [T; count] {\n    [value; count]\n}\n\n// inference keeps literal lengths\nconst rgb = copy<uint8, 3>([255, 128, 0]);\nconst names = repeat(\"destack\", 2);\n\nrgb satisfies Buffer<3>;\nnames satisfies [string; 2];\n"
    },
    "types/constraints": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Constraints describe the interfaces needed by a generic declaration.</span>\n<span data-k=\"comment\">* `where` keeps larger constraint sets readable.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">interface</span> <span data-k=\"type\">Comparable</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">compare</span><span data-k=\"punct\">(</span><span data-k=\"name\">other</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">interface</span> <span data-k=\"type\">Encoder</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">encode</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// `where` keeps larger bounds grouped with the declaration</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">chooseStable</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">left</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">,</span> <span data-k=\"name\">right</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span> where <span data-k=\"punct\">(</span>\n    <span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Comparable</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span>\n    <span data-k=\"type\">T</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Encoder</span><span data-k=\"punct\">,</span>\n<span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">left</span><span data-k=\"punct\">.</span><span data-k=\"name\">compare</span><span data-k=\"punct\">(</span><span data-k=\"name\">right</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">&lt;=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">left</span>\n    <span data-k=\"punct\">}</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">right</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// concrete arguments select the required implementations</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">a</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Version</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">b</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Version</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">chooseStable</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Version</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">a</span><span data-k=\"punct\">,</span> <span data-k=\"name\">b</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Version</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Constraints describe the interfaces needed by a generic declaration.\n* `where` keeps larger constraint sets readable.\n*/\n\ninterface Comparable<T> {\n    compare(other: T): int32;\n}\n\ninterface Encoder {\n    encode(): [uint8];\n}\n\n// `where` keeps larger bounds grouped with the declaration\nfunction chooseStable<T>(left: T, right: T): T where (\n    T: Comparable<T>,\n    T: Encoder,\n) {\n    if (left.compare(right) <= 0) {\n        left\n    } else {\n        right\n    }\n}\n\n// concrete arguments select the required implementations\ndeclare const a: Version;\ndeclare const b: Version;\nchooseStable<Version>(a, b) satisfies Version;\n"
    },
    "types/associated": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Associated types and constants belong to the interface implementation.</span>\n<span data-k=\"comment\">* They are statically selected and occupy no instance space.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Option</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:option&quot;</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">IOError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">interface</span> <span data-k=\"type\">Iterator</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Item</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">next</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Option</span><span data-k=\"punct\">&lt;</span>this<span data-k=\"punct\">.</span><span data-k=\"type\">Item</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">interface</span> <span data-k=\"type\">RegisterBlock</span> <span data-k=\"punct\">{</span>\n    comptime <span data-k=\"keyword\">const</span> <span data-k=\"type\">Width</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"comment\">// associated constants can shape method types</span>\n    <span data-k=\"name\">read</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> this<span data-k=\"punct\">.</span><span data-k=\"type\">Width</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">write</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> this<span data-k=\"punct\">.</span><span data-k=\"type\">Width</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// associated result types flow through generics</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">collect</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">I</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Iterator</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">items</span><span data-k=\"punct\">:</span> <span data-k=\"type\">I</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">I</span><span data-k=\"punct\">.</span><span data-k=\"type\">Item</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">items</span><span data-k=\"punct\">.</span><span data-k=\"name\">toArray</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Associated types and constants belong to the interface implementation.\n* They are statically selected and occupy no instance space.\n*/\n\nimport { Result } from \"destack:error\";\nimport { Option } from \"destack:option\";\n\nstruct IOError {\n    message: string;\n}\n\ninterface Iterator {\n    type Item;\n\n    next(): Option<this.Item>;\n}\n\ninterface RegisterBlock {\n    comptime const Width: uint;\n\n    // associated constants can shape method types\n    read(): [uint8; this.Width];\n    write(bytes: &[uint8; this.Width]): Result<void, IOError>;\n}\n\n// associated result types flow through generics\nfunction collect<I: Iterator>(items: I): I.Item[] {\n    items.toArray()\n}\n"
    },
    "types/reflection": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Types can be reflected as values and evaluated at comptime.</span>\n<span data-k=\"comment\">* Layout queries stay in the static world unless explicitly used at runtime.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">age</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Body</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">headers</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">body</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Body</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// type values can be carried at runtime</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"type\">UserType</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Type</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"type\">SameUserType</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Type</span><span data-k=\"punct\">.</span><span data-k=\"name\">of</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// layout queries can run at comptime</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">userSize</span> <span data-k=\"punct\">=</span> comptime <span data-k=\"name\">sizeOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">requestLayout</span> <span data-k=\"punct\">=</span> comptime <span data-k=\"name\">layoutOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">InlineBytes</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"name\">sizeOf</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">userSize</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">usize</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">requestLayout</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">TypeLayout</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Types can be reflected as values and evaluated at comptime.\n* Layout queries stay in the static world unless explicitly used at runtime.\n*/\n\nstruct User {\n    name: string;\n    age: uint;\n}\n\nstruct Request<Body> {\n    headers: string[];\n    body: Body;\n}\n\n// type values can be carried at runtime\nconst UserType: Type<User> = User;\nconst SameUserType = Type.of<User>();\n\n// layout queries can run at comptime\nconst userSize = comptime sizeOf<User>();\nconst requestLayout = comptime layoutOf<Request<string>>();\n\ntype InlineBytes<T> = [uint8; sizeOf<T>()];\n\nuserSize satisfies usize;\nrequestLayout satisfies TypeLayout;\n"
    },
    "types/tagged-unions": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Tagged unions are ordinary nominal unions with a shared discriminant.</span>\n<span data-k=\"comment\">* Userland macros can derive the constructor and pattern helpers.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Tagged</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:decorator&quot;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// the macro derives constructors from the shared tag</span>\n@<span data-k=\"name\">derive</span><span data-k=\"punct\">(</span><span data-k=\"type\">Tagged</span><span data-k=\"punct\">)</span>\nnewtype <span data-k=\"type\">Shape</span> <span data-k=\"punct\">=</span>\n    <span data-k=\"punct\">|</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">kind</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;rectangle&quot;</span><span data-k=\"punct\">;</span> <span data-k=\"name\">width</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span> <span data-k=\"name\">height</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">}</span>\n    <span data-k=\"punct\">|</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">kind</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;circle&quot;</span><span data-k=\"punct\">;</span> <span data-k=\"name\">radius</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\nextension <span data-k=\"keyword\">of</span> <span data-k=\"type\">Shape</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">static</span> <span data-k=\"name\">DEFAULT</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"name\">Rectangle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span>\n        <span data-k=\"name\">width</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">10</span><span data-k=\"punct\">,</span>\n        <span data-k=\"name\">height</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">20</span><span data-k=\"punct\">,</span>\n    <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"comment\">// match arms narrow each variant payload</span>\n    <span data-k=\"name\">area</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">{</span>\n        match <span data-k=\"punct\">(</span>this<span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n            <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"name\">Rectangle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"name\">width</span><span data-k=\"punct\">,</span> <span data-k=\"name\">height</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">width</span> <span data-k=\"punct\">*</span> <span data-k=\"name\">height</span>\n            <span data-k=\"type\">Shape</span><span data-k=\"punct\">.</span><span data-k=\"name\">Circle</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"name\">radius</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">radius</span> <span data-k=\"punct\">*</span> <span data-k=\"name\">radius</span>\n        <span data-k=\"punct\">}</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Tagged unions are ordinary nominal unions with a shared discriminant.\n* Userland macros can derive the constructor and pattern helpers.\n*/\n\nimport { Tagged } from \"destack:decorator\";\n\n// the macro derives constructors from the shared tag\n@derive(Tagged)\nnewtype Shape =\n    | { kind: \"rectangle\"; width: int32; height: int32 }\n    | { kind: \"circle\"; radius: int32 };\n\nextension of Shape {\n    static DEFAULT = Shape.Rectangle({\n        width: 10,\n        height: 20,\n    });\n\n    // match arms narrow each variant payload\n    area(): int32 {\n        match (this) {\n            Shape.Rectangle({ width, height }) => width * height\n            Shape.Circle({ radius }) => radius * radius\n        }\n    }\n}\n"
    },
    "types/static": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Static terms are known during inference and can shape declarations.</span>\n<span data-k=\"comment\">* `@if` removes fields or statements once generic values are known.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">InlineIndex</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span>\nstruct <span data-k=\"type\">ExternalIndex</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// the mode value controls the stored shape</span>\nstruct <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">,</span> comptime <span data-k=\"type\">Mode</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;inline&quot;</span> <span data-k=\"punct\">|</span> <span data-k=\"string\">&quot;external&quot;</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    @<span data-k=\"name\">if</span><span data-k=\"punct\">(</span><span data-k=\"type\">Mode</span> <span data-k=\"punct\">==</span> <span data-k=\"string\">&quot;inline&quot;</span><span data-k=\"punct\">)</span>\n    <span data-k=\"name\">index</span><span data-k=\"punct\">:</span> <span data-k=\"type\">InlineIndex</span><span data-k=\"punct\">;</span>\n\n    @<span data-k=\"name\">if</span><span data-k=\"punct\">(</span><span data-k=\"type\">Mode</span> <span data-k=\"punct\">==</span> <span data-k=\"string\">&quot;external&quot;</span><span data-k=\"punct\">)</span>\n    <span data-k=\"name\">index</span><span data-k=\"punct\">:</span> <span data-k=\"type\">ExternalIndex</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">data</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// branches collapse once the static value is known</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">width</span><span data-k=\"punct\">&lt;</span>comptime <span data-k=\"type\">Wide</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Wide</span> <span data-k=\"keyword\">extends</span> <span data-k=\"literal\">true</span> <span data-k=\"punct\">?</span> <span data-k=\"literal\">8</span> <span data-k=\"punct\">:</span> <span data-k=\"literal\">4</span> <span data-k=\"punct\">{</span>\n    @<span data-k=\"keyword\">if</span><span data-k=\"punct\">(</span><span data-k=\"type\">Wide</span><span data-k=\"punct\">)</span>\n    <span data-k=\"keyword\">return</span> <span data-k=\"literal\">8</span><span data-k=\"punct\">;</span>\n\n    @<span data-k=\"keyword\">if</span><span data-k=\"punct\">(</span><span data-k=\"punct\">!</span><span data-k=\"type\">Wide</span><span data-k=\"punct\">)</span>\n    <span data-k=\"keyword\">return</span> <span data-k=\"literal\">4</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Static terms are known during inference and can shape declarations.\n* `@if` removes fields or statements once generic values are known.\n*/\n\nstruct InlineIndex {}\nstruct ExternalIndex {}\n\n// the mode value controls the stored shape\nstruct Buffer<T, comptime Mode: \"inline\" | \"external\"> {\n    @if(Mode == \"inline\")\n    index: InlineIndex;\n\n    @if(Mode == \"external\")\n    index: ExternalIndex;\n\n    data: T[];\n}\n\n// branches collapse once the static value is known\nfunction width<comptime Wide: boolean>(): Wide extends true ? 8 : 4 {\n    @if(Wide)\n    return 8;\n\n    @if(!Wide)\n    return 4;\n}\n"
    },
    "types/any": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Native `.ds` rejects `any`.</span>\n<span data-k=\"comment\">* Use `unknown` for untrusted values and `Any&lt;T&gt;` for explicit runtime erasure.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">IOError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">readInput</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">unknown</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">any</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">readInput</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n            <span data-k=\"inline-diagnostic-shadow\"><span data-k=\"inline-diagnostic-box\"><span data-k=\"squiggle\">~~~</span>\n<span data-k=\"message\">error: 'any' is not available in .ds files</span></span></span>\n\n<span data-k=\"comment\">// unknown keeps the boundary explicit</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">input</span><span data-k=\"punct\">:</span> <span data-k=\"type\">unknown</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">readInput</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">input</span> is <span data-k=\"name\">string</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">input</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">interface</span> <span data-k=\"type\">Writer</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">write</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">uint</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// erased interfaces are explicit runtime wrappers</span>\nstruct <span data-k=\"type\">RuntimeLogger</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"comment\">// explicit erasure is visible in the type</span>\n    <span data-k=\"name\">writer</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Any</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Writer</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Native `.ds` rejects `any`.\n* Use `unknown` for untrusted values and `Any<T>` for explicit runtime erasure.\n*/\n\nimport { Result } from \"destack:error\";\n\nstruct IOError {\n    message: string;\n}\n\ndeclare function readInput(): unknown;\n\nlet value: any = readInput();\n            ~~~\n            error: 'any' is not available in .ds files\n\n// unknown keeps the boundary explicit\nlet input: unknown = readInput();\n\nif (input is string) {\n    input satisfies string;\n}\n\ninterface Writer {\n    write(bytes: [uint8]): Result<uint, IOError>;\n}\n\n// erased interfaces are explicit runtime wrappers\nstruct RuntimeLogger {\n    // explicit erasure is visible in the type\n    writer: Any<Writer>;\n}\n"
    },
    "expressions/blocks": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* In Destack, all expressions are values, much like in Rust.</span>\n<span data-k=\"comment\">* Blocks can compute values without introducing object literal ambiguity.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n\nnewtype <span data-k=\"type\">UserId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">condition</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">loadUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">UserRecord</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">userFromRecord</span><span data-k=\"punct\">(</span><span data-k=\"name\">record</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserRecord</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// `if`s and `block`s produce values</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">value</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">condition</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"literal\">2</span>\n<span data-k=\"punct\">}</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"literal\">4</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">value</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"literal\">2</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">4</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// do blocks disambiguate from `{ .. }` object literals</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">do</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">record</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">loadUser</span><span data-k=\"punct\">(</span><span data-k=\"type\">UserId</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">userFromRecord</span><span data-k=\"punct\">(</span><span data-k=\"name\">record</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">user</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">User</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// this also works in functions</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">add</span><span data-k=\"punct\">(</span><span data-k=\"name\">left</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">,</span> <span data-k=\"name\">right</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">left</span> <span data-k=\"punct\">+</span> <span data-k=\"name\">right</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* In Destack, all expressions are values, much like in Rust.\n* Blocks can compute values without introducing object literal ambiguity.\n*/\n\nimport { Result } from \"destack:error\";\n\nnewtype UserId = uint64;\n\ndeclare const condition: boolean;\ndeclare function loadUser(id: UserId): Result<UserRecord, IOError>;\ndeclare function userFromRecord(record: UserRecord): User;\n\n// `if`s and `block`s produce values\nconst value = if (condition) {\n    2\n} else {\n    4\n};\nvalue satisfies 2 | 4;\n\n// do blocks disambiguate from `{ .. }` object literals\nconst user = do {\n    const record = loadUser(UserId(1))?;\n    userFromRecord(record)\n};\nuser satisfies User;\n\n// this also works in functions\nfunction add(left: int32, right: int32): int32 {\n    left + right\n}\n"
    },
    "expressions/patterns": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Destructuring uses the same pattern families as match arms.</span>\n<span data-k=\"comment\">* Irrefutable patterns bind names directly in let declarations.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">Header</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">requestId</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">retries</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">Packet</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">header</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Header</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">4</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">packet</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Packet</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// struct patterns keep nominal identity explicit</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"type\">Packet</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">header</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Header</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">requestId</span><span data-k=\"punct\">,</span> <span data-k=\"name\">retries</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">,</span>\n    <span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"name\">tag</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">..</span><span data-k=\"punct\">.</span><span data-k=\"name\">payload</span><span data-k=\"punct\">]</span><span data-k=\"punct\">,</span>\n<span data-k=\"punct\">}</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">packet</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// bindings inherit precise field and element types</span>\n<span data-k=\"name\">requestId</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">retries</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">tag</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">payload</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Destructuring uses the same pattern families as match arms.\n* Irrefutable patterns bind names directly in let declarations.\n*/\n\nstruct Header {\n    requestId: string;\n    retries: uint8;\n}\n\nstruct Packet {\n    header: Header;\n    bytes: [uint8; 4];\n}\n\ndeclare const packet: Packet;\n\n// struct patterns keep nominal identity explicit\nlet Packet {\n    header: Header { requestId, retries },\n    bytes: [tag, ...payload],\n} = packet;\n\n// bindings inherit precise field and element types\nrequestId satisfies string;\nretries satisfies uint8;\ntag satisfies uint8;\npayload satisfies [uint8; 3];\n"
    },
    "expressions/let-else": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Let else handles refutable patterns without nesting the success path.</span>\n<span data-k=\"comment\">* Bindings are available only after the pattern has succeeded.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">Header</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">size</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint32</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">checksum</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint32</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">DecodeError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">decodeHeader</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Header</span> <span data-k=\"punct\">|</span> <span data-k=\"literal\">null</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">decodeError</span><span data-k=\"punct\">(</span><span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">DecodeError</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">frameSize</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">uint32</span><span data-k=\"punct\">,</span> <span data-k=\"type\">DecodeError</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">let</span> <span data-k=\"type\">Header</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">size</span><span data-k=\"punct\">,</span> <span data-k=\"name\">checksum</span><span data-k=\"punct\">:</span> <span data-k=\"name\">_</span> <span data-k=\"punct\">}</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">decodeHeader</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">)</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"keyword\">return</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">.</span><span data-k=\"name\">err</span><span data-k=\"punct\">(</span><span data-k=\"name\">decodeError</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;missing header&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"comment\">// annotations can refine the successful binding</span>\n    <span data-k=\"keyword\">let</span> <span data-k=\"name\">checked</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">1048576</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">size</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"keyword\">return</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">.</span><span data-k=\"name\">err</span><span data-k=\"punct\">(</span><span data-k=\"name\">decodeError</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;frame too large&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"type\">Result</span><span data-k=\"punct\">.</span><span data-k=\"name\">ok</span><span data-k=\"punct\">(</span><span data-k=\"name\">checked</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Let else handles refutable patterns without nesting the success path.\n* Bindings are available only after the pattern has succeeded.\n*/\n\nimport { Result } from \"destack:error\";\n\nstruct Header {\n    size: uint32;\n    checksum: uint32;\n}\n\nstruct DecodeError {\n    message: string;\n}\n\ndeclare function decodeHeader(bytes: [uint8]): Header | null;\ndeclare function decodeError(message: string): DecodeError;\n\nfunction frameSize(bytes: [uint8]): Result<uint32, DecodeError> {\n    let Header { size, checksum: _ } = decodeHeader(bytes) else {\n        return Result.err(decodeError(\"missing header\"));\n    };\n\n    // annotations can refine the successful binding\n    let checked: 0..=1048576 = size else {\n        return Result.err(decodeError(\"frame too large\"));\n    };\n\n    Result.ok(checked)\n}\n"
    },
    "expressions/match": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Match expressions are exhaustive and return the joined arm type.</span>\n<span data-k=\"comment\">* Arms can mix nominal patterns, ranges, literals, and guards.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Err</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Ok</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n\nnewtype <span data-k=\"type\">UserId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">MissingUser</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">DecodeError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">offset</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint32</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">describe</span><span data-k=\"punct\">(</span><span data-k=\"name\">result</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">MissingUser</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">DecodeError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span>\n    match <span data-k=\"punct\">(</span><span data-k=\"name\">result</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"type\">Ok</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">id</span><span data-k=\"punct\">,</span> <span data-k=\"name\">name</span> <span data-k=\"punct\">}</span> <span data-k=\"punct\">}</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">`${id}: ${name}`</span>\n        <span data-k=\"type\">Err</span> <span data-k=\"punct\">{</span> <span data-k=\"message\">error: MissingUser { id } } =&gt; `missing ${id}`</span>\n        <span data-k=\"type\">Err</span> <span data-k=\"punct\">{</span> <span data-k=\"message\">error: DecodeError { offset: 0..=255 } } =&gt; &quot;bad header&quot;</span>\n        <span data-k=\"type\">Err</span> <span data-k=\"punct\">{</span> <span data-k=\"message\">error: DecodeError { offset } } =&gt; `bad body at ${offset}`</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Match expressions are exhaustive and return the joined arm type.\n* Arms can mix nominal patterns, ranges, literals, and guards.\n*/\n\nimport { Err, Ok, Result } from \"destack:error\";\n\nnewtype UserId = uint64;\n\nstruct User {\n    id: UserId;\n    name: string;\n}\n\nstruct MissingUser {\n    id: UserId;\n}\n\nstruct DecodeError {\n    offset: uint32;\n}\n\nfunction describe(result: Result<User, MissingUser | DecodeError>): string {\n    match (result) {\n        Ok { value: User { id, name } } => `${id}: ${name}`\n        Err { error: MissingUser { id } } => `missing ${id}`\n        Err { error: DecodeError { offset: 0..=255 } } => \"bad header\"\n        Err { error: DecodeError { offset } } => `bad body at ${offset}`\n    }\n}\n"
    },
    "expressions/is": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* `value is T` asks whether the runtime representation carries `T`.</span>\n<span data-k=\"comment\">* The check returns `boolean` and narrows the current branch.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// a successful check narrows to User in this branch</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">label</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">value</span> is <span data-k=\"type\">User</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">value</span><span data-k=\"punct\">.</span><span data-k=\"name\">name</span>\n    <span data-k=\"punct\">}</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">value</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">int32</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// scalar checks narrow ordinary unions too</span>\n<span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">value</span> is <span data-k=\"name\">string</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">value</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">value</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* `value is T` asks whether the runtime representation carries `T`.\n* The check returns `boolean` and narrows the current branch.\n*/\n\nstruct User {\n    name: string;\n}\n\n// a successful check narrows to User in this branch\nfunction label(value: User | string): string {\n    if (value is User) {\n        value.name\n    } else {\n        value\n    }\n}\n\nconst value: string | int32 = 1;\n\n// scalar checks narrow ordinary unions too\nif (value is string) {\n    value satisfies string;\n} else {\n    value satisfies int32;\n}\n"
    },
    "expressions/loops": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Loops are expressions when a label names their break value.</span>\n<span data-k=\"comment\">* Plain `for` loops remain familiar TypeScript-shaped iteration.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">readInput</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">process</span><span data-k=\"punct\">(</span><span data-k=\"name\">line</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// labeled loop breaks produce the expression value</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">status</span> <span data-k=\"punct\">=</span> input<span data-k=\"punct\">:</span> loop <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">line</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">readInput</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">line</span> <span data-k=\"punct\">===</span> <span data-k=\"string\">&quot;quit&quot;</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"keyword\">break</span> input<span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;done&quot;</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n\n    <span data-k=\"name\">process</span><span data-k=\"punct\">(</span><span data-k=\"name\">line</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// ordinary counted loops stay familiar</span>\n<span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">let</span> <span data-k=\"name\">retry</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span> <span data-k=\"name\">retry</span> <span data-k=\"punct\">&lt;</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">;</span> <span data-k=\"name\">retry</span><span data-k=\"punct\">++</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">process</span><span data-k=\"punct\">(</span><span data-k=\"string\">`attempt ${retry}`</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"name\">status</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;done&quot;</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Loops are expressions when a label names their break value.\n* Plain `for` loops remain familiar TypeScript-shaped iteration.\n*/\n\ndeclare function readInput(): string;\ndeclare function process(line: string): void;\n\n// labeled loop breaks produce the expression value\nconst status = input: loop {\n    const line = readInput();\n\n    if (line === \"quit\") {\n        break input: \"done\";\n    }\n\n    process(line);\n};\n\n// ordinary counted loops stay familiar\nfor (let retry = 0; retry < 3; retry++) {\n    process(`attempt ${retry}`);\n}\n\nstatus satisfies \"done\";\n"
    },
    "expressions/using": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* `using` is lexical cleanup separate from `Drop`.</span>\n<span data-k=\"comment\">* Cleanup runs on fallthrough, return, break, continue, and `?`.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">interface</span> <span data-k=\"type\">DatabaseConnection</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">query</span><span data-k=\"punct\">(</span><span data-k=\"name\">sql</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Row</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">,</span> <span data-k=\"type\">DatabaseError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">interface</span> <span data-k=\"type\">DatabasePool</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">connect</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">DatabaseConnection</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">openFile</span><span data-k=\"punct\">(</span><span data-k=\"name\">path</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">File</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">copy</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">:</span> <span data-k=\"type\">File</span><span data-k=\"punct\">,</span> <span data-k=\"name\">output</span><span data-k=\"punct\">:</span> <span data-k=\"type\">File</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">index</span><span data-k=\"punct\">(</span><span data-k=\"name\">file</span><span data-k=\"punct\">:</span> <span data-k=\"type\">File</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">pool</span><span data-k=\"punct\">:</span> <span data-k=\"type\">DatabasePool</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">files</span><span data-k=\"punct\">:</span> <span data-k=\"type\">File</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">copyFile</span><span data-k=\"punct\">(</span><span data-k=\"name\">inputPath</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"name\">outputPath</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"comment\">// resources dispose in reverse declaration order</span>\n    using <span data-k=\"name\">input</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">openFile</span><span data-k=\"punct\">(</span><span data-k=\"name\">inputPath</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span>\n    using <span data-k=\"name\">output</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">openFile</span><span data-k=\"punct\">(</span><span data-k=\"name\">outputPath</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">copy</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">,</span> <span data-k=\"name\">output</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">async</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">query</span><span data-k=\"punct\">(</span><span data-k=\"name\">sql</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Row</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">,</span> <span data-k=\"type\">DatabaseError</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"comment\">// async cleanup is awaited at scope exit</span>\n    <span data-k=\"keyword\">await</span> using <span data-k=\"name\">connection</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">await</span> <span data-k=\"name\">pool</span><span data-k=\"punct\">.</span><span data-k=\"name\">connect</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"keyword\">await</span> <span data-k=\"name\">connection</span><span data-k=\"punct\">.</span><span data-k=\"name\">query</span><span data-k=\"punct\">(</span><span data-k=\"name\">sql</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// loop resources are cleaned up after each iteration</span>\n<span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span>using <span data-k=\"name\">file</span> <span data-k=\"keyword\">of</span> <span data-k=\"name\">files</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">index</span><span data-k=\"punct\">(</span><span data-k=\"name\">file</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* `using` is lexical cleanup separate from `Drop`.\n* Cleanup runs on fallthrough, return, break, continue, and `?`.\n*/\n\nimport { Result } from \"destack:error\";\n\ninterface DatabaseConnection {\n    query(sql: string): Result<Row[], DatabaseError>;\n}\n\ninterface DatabasePool {\n    connect(): Promise<DatabaseConnection>;\n}\n\ndeclare function openFile(path: string): Result<File, IOError>;\ndeclare function copy(input: File, output: File): Result<void, IOError>;\ndeclare function index(file: File): Result<void, IOError>;\ndeclare const pool: DatabasePool;\ndeclare const files: File[];\n\nfunction copyFile(inputPath: string, outputPath: string): Result<void, IOError> {\n    // resources dispose in reverse declaration order\n    using input = openFile(inputPath)?;\n    using output = openFile(outputPath)?;\n\n    copy(input, output)\n}\n\nasync function query(sql: string): Result<Row[], DatabaseError> {\n    // async cleanup is awaited at scope exit\n    await using connection = await pool.connect();\n\n    await connection.query(sql)\n}\n\n// loop resources are cleaned up after each iteration\nfor (using file of files) {\n    index(file)?;\n}\n"
    },
    "expressions/ranges": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Ranges are half-open by default and implement `RangeBounds&lt;T&gt;`.</span>\n<span data-k=\"comment\">* Inclusive ranges use `..=` when the end bound is included.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">values</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint32</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"literal\">10</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">20</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">30</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">40</span><span data-k=\"punct\">,</span> <span data-k=\"literal\">50</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// slice indexing accepts all range bounds</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">middle</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">values</span><span data-k=\"punct\">[</span><span data-k=\"literal\">1</span><span data-k=\"punct\">..</span><span data-k=\"literal\">4</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">prefix</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">values</span><span data-k=\"punct\">[</span><span data-k=\"punct\">..</span><span data-k=\"literal\">3</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">suffix</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">values</span><span data-k=\"punct\">[</span><span data-k=\"literal\">2</span><span data-k=\"punct\">..</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">whole</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">values</span><span data-k=\"punct\">[</span><span data-k=\"punct\">..</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">middle</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint32</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">prefix</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint32</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">suffix</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint32</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">whole</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint32</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">HttpStatus</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">100</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">599</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">LogEntry</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">status</span><span data-k=\"punct\">:</span> <span data-k=\"type\">HttpStatus</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">scan</span><span data-k=\"punct\">(</span><span data-k=\"name\">range</span><span data-k=\"punct\">:</span> <span data-k=\"type\">RangeBounds</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">usize</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">LogEntry</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// ranges can be passed as first-class bounds</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">recent</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">scan</span><span data-k=\"punct\">(</span><span data-k=\"literal\">0</span><span data-k=\"punct\">..</span><span data-k=\"literal\">100</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">tail</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">scan</span><span data-k=\"punct\">(</span><span data-k=\"literal\">100</span><span data-k=\"punct\">..</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// range patterns classify scalar values</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">kind</span> <span data-k=\"punct\">=</span> match <span data-k=\"punct\">(</span><span data-k=\"name\">status</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"literal\">200</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">299</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;ok&quot;</span>\n    <span data-k=\"literal\">400</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">499</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;client-error&quot;</span>\n    <span data-k=\"literal\">500</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">599</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;server-error&quot;</span>\n    <span data-k=\"name\">_</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"string\">&quot;other&quot;</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Ranges are half-open by default and implement `RangeBounds<T>`.\n* Inclusive ranges use `..=` when the end bound is included.\n*/\n\nlet values: [uint32] = [10, 20, 30, 40, 50];\n\n// slice indexing accepts all range bounds\nconst middle = values[1..4];\nconst prefix = values[..3];\nconst suffix = values[2..];\nconst whole = values[..];\n\nmiddle satisfies [uint32];\nprefix satisfies [uint32];\nsuffix satisfies [uint32];\nwhole satisfies [uint32];\n\ntype HttpStatus = 100..=599;\n\nstruct LogEntry {\n    message: string;\n}\n\ndeclare const status: HttpStatus;\ndeclare function scan(range: RangeBounds<usize>): [LogEntry];\n\n// ranges can be passed as first-class bounds\nconst recent = scan(0..100);\nconst tail = scan(100..);\n\n// range patterns classify scalar values\nconst kind = match (status) {\n    200..=299 => \"ok\"\n    400..=499 => \"client-error\"\n    500..=599 => \"server-error\"\n    _ => \"other\"\n};\n"
    },
    "expressions/overloads": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Dispatch selects calls and operators using TypeScript-shaped overload rules.</span>\n<span data-k=\"comment\">* Operators resolve through the corresponding nominal interface.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Add</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:ops&quot;</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">Vector2</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">float32</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// the left operand is the receiver implementation</span>\nextension <span data-k=\"keyword\">of</span> <span data-k=\"type\">Vector2</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">Add</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Vector2</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">type</span> <span data-k=\"type\">Output</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Vector2</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">add</span><span data-k=\"punct\">(</span><span data-k=\"name\">other</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Vector2</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> this<span data-k=\"punct\">.</span><span data-k=\"type\">Output</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"type\">Vector2</span> <span data-k=\"punct\">{</span>\n            <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> this<span data-k=\"punct\">.</span><span data-k=\"name\">x</span> <span data-k=\"punct\">+</span> <span data-k=\"name\">other</span><span data-k=\"punct\">.</span><span data-k=\"name\">x</span><span data-k=\"punct\">,</span>\n            <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> this<span data-k=\"punct\">.</span><span data-k=\"name\">y</span> <span data-k=\"punct\">+</span> <span data-k=\"name\">other</span><span data-k=\"punct\">.</span><span data-k=\"name\">y</span><span data-k=\"punct\">,</span>\n        <span data-k=\"punct\">}</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// operator syntax dispatches through Add</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">position</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Vector2</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">offset</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Vector2</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">moved</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">position</span> <span data-k=\"punct\">+</span> <span data-k=\"name\">offset</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">moved</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Vector2</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Dispatch selects calls and operators using TypeScript-shaped overload rules.\n* Operators resolve through the corresponding nominal interface.\n*/\n\nimport { Add } from \"destack:ops\";\n\nstruct Vector2 {\n    x: float32;\n    y: float32;\n}\n\n// the left operand is the receiver implementation\nextension of Vector2 implements Add<Vector2> {\n    type Output = Vector2;\n\n    add(other: Vector2): this.Output {\n        Vector2 {\n            x: this.x + other.x,\n            y: this.y + other.y,\n        }\n    }\n}\n\n// operator syntax dispatches through Add\ndeclare const position: Vector2;\ndeclare const offset: Vector2;\nconst moved = position + offset;\nmoved satisfies Vector2;\n"
    },
    "expressions/errors": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Native Destack code is Result-first and does not use exceptions.</span>\n<span data-k=\"comment\">* `?`, `!`, and `try` open explicit error and absence values.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">Config</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">source</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">IOError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">path</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">ParseError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">line</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint32</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">readConfig</span><span data-k=\"punct\">(</span><span data-k=\"name\">path</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">parseConfig</span><span data-k=\"punct\">(</span><span data-k=\"name\">text</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Config</span><span data-k=\"punct\">,</span> <span data-k=\"type\">ParseError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">defaultConfig</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Config</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">loadConfig</span><span data-k=\"punct\">(</span><span data-k=\"name\">path</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Config</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span> <span data-k=\"punct\">|</span> <span data-k=\"type\">ParseError</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"comment\">// Result values cannot be used until opened</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">text</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">readConfig</span><span data-k=\"punct\">(</span><span data-k=\"name\">path</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n                 <span data-k=\"inline-diagnostic-shadow\"><span data-k=\"inline-diagnostic-box\"><span data-k=\"squiggle\">~~~~~~~~~~~~~~~~</span>\n<span data-k=\"message\">error: Result&lt;string, IOError&gt; is not string</span></span></span>\n\n    <span data-k=\"comment\">// `?` opens success and propagates failure</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">config</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">parseConfig</span><span data-k=\"punct\">(</span><span data-k=\"name\">text</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"type\">Result</span><span data-k=\"punct\">.</span><span data-k=\"name\">ok</span><span data-k=\"punct\">(</span><span data-k=\"name\">config</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// `try` scopes the propagation and matches the error</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">config</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">try</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">loadConfig</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;destack.json&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span>\n<span data-k=\"punct\">}</span> <span data-k=\"keyword\">catch</span> match <span data-k=\"punct\">(</span><span data-k=\"name\">error</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"type\">IOError</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">path</span><span data-k=\"punct\">:</span> <span data-k=\"name\">_</span> <span data-k=\"punct\">}</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">defaultConfig</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span>\n    <span data-k=\"type\">ParseError</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">line</span><span data-k=\"punct\">:</span> <span data-k=\"name\">_</span> <span data-k=\"punct\">}</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">defaultConfig</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Native Destack code is Result-first and does not use exceptions.\n* `?`, `!`, and `try` open explicit error and absence values.\n*/\n\nimport { Result } from \"destack:error\";\n\nstruct Config {\n    source: string;\n}\n\nstruct IOError {\n    path: string;\n}\n\nstruct ParseError {\n    line: uint32;\n}\n\ndeclare function readConfig(path: string): Result<string, IOError>;\ndeclare function parseConfig(text: string): Result<Config, ParseError>;\ndeclare function defaultConfig(): Config;\n\nfunction loadConfig(path: string): Result<Config, IOError | ParseError> {\n    // Result values cannot be used until opened\n    const text = readConfig(path);\n                 ~~~~~~~~~~~~~~~~\n                 error: Result<string, IOError> is not string\n\n    // `?` opens success and propagates failure\n    const config = parseConfig(text)?;\n\n    Result.ok(config)\n}\n\n// `try` scopes the propagation and matches the error\nconst config = try {\n    loadConfig(\"destack.json\")?\n} catch match (error) {\n    IOError { path: _ } => defaultConfig()\n    ParseError { line: _ } => defaultConfig()\n};\n"
    },
    "expressions/tsx": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* TSX is a syntax for tree-shaped values.</span>\n<span data-k=\"comment\">* The active tree builder comes from module metadata.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">HtmlTree</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:ui/html&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Log</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Panel</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Status</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;../components&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">build</span><span data-k=\"punct\">,</span> <span data-k=\"name\">events</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;../state&quot;</span><span data-k=\"punct\">;</span>\n\nmodule <span data-k=\"punct\">{</span>\n    <span data-k=\"comment\">// this module uses the html tree builder</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">tree</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">HtmlTree</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// jsx syntax lowers into tree builder calls</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">view</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span>\n    <span data-k=\"punct\">&lt;</span><span data-k=\"type\">Panel</span> <span data-k=\"name\">title</span><span data-k=\"punct\">=</span><span data-k=\"string\">&quot;build&quot;</span><span data-k=\"punct\">&gt;</span>\n        <span data-k=\"punct\">&lt;</span><span data-k=\"type\">Status</span> <span data-k=\"name\">state</span><span data-k=\"punct\">=</span><span data-k=\"punct\">{</span><span data-k=\"name\">build</span><span data-k=\"punct\">.</span><span data-k=\"name\">state</span><span data-k=\"punct\">}</span> <span data-k=\"punct\">/&gt;</span>\n        <span data-k=\"punct\">&lt;</span><span data-k=\"type\">Log</span> <span data-k=\"name\">lines</span><span data-k=\"punct\">=</span><span data-k=\"punct\">{</span><span data-k=\"name\">events</span><span data-k=\"punct\">}</span> <span data-k=\"punct\">/&gt;</span>\n    <span data-k=\"punct\">&lt;/</span><span data-k=\"type\">Panel</span><span data-k=\"punct\">&gt;</span>\n<span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* TSX is a syntax for tree-shaped values.\n* The active tree builder comes from module metadata.\n*/\n\nimport { HtmlTree } from \"destack:ui/html\";\nimport { Log, Panel, Status } from \"../components\";\nimport { build, events } from \"../state\";\n\nmodule {\n    // this module uses the html tree builder\n    const tree = HtmlTree;\n}\n\n// jsx syntax lowers into tree builder calls\nconst view = (\n    <Panel title=\"build\">\n        <Status state={build.state} />\n        <Log lines={events} />\n    </Panel>\n);\n"
    },
    "expressions/decorators": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Decorators are unified annotations whose target decides the behavior.</span>\n<span data-k=\"comment\">* Providers can remain inert or implement macro and diagnostic protocols.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Clone</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Debug</span><span data-k=\"punct\">,</span> <span data-k=\"name\">derive</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:decorator&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n\nnewtype <span data-k=\"type\">UserId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span>\nnewtype <span data-k=\"type\">deprecated</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">|</span> <span data-k=\"punct\">(</span><span data-k=\"type\">string</span><span data-k=\"punct\">,</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">LoadError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// inert annotations can still carry typed data</span>\n@<span data-k=\"name\">deprecated</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;use loadUser instead&quot;</span><span data-k=\"punct\">)</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">readUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">LoadError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// derive-style providers are ordinary decorators</span>\n@<span data-k=\"name\">derive</span><span data-k=\"punct\">(</span><span data-k=\"type\">Clone</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Debug</span><span data-k=\"punct\">)</span>\nstruct <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// diagnostics can be configured with structured arguments</span>\n@<span data-k=\"name\">allow</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;no-floating-promises&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">if</span><span data-k=\"punct\">:</span> <span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">dev</span><span data-k=\"punct\">,</span>\n    <span data-k=\"name\">otherwise</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;deny&quot;</span><span data-k=\"punct\">,</span>\n    <span data-k=\"name\">reason</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;debug telemetry&quot;</span><span data-k=\"punct\">,</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">)</span>\nmodule <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Decorators are unified annotations whose target decides the behavior.\n* Providers can remain inert or implement macro and diagnostic protocols.\n*/\n\nimport { Clone, Debug, derive } from \"destack:decorator\";\nimport { Result } from \"destack:error\";\n\nnewtype UserId = uint64;\nnewtype deprecated = () | (string,);\n\nstruct LoadError {\n    message: string;\n}\n\n// inert annotations can still carry typed data\n@deprecated(\"use loadUser instead\")\ndeclare function readUser(id: UserId): Result<User, LoadError>;\n\n// derive-style providers are ordinary decorators\n@derive(Clone, Debug)\nstruct User {\n    id: UserId;\n    name: string;\n}\n\n// diagnostics can be configured with structured arguments\n@allow(\"no-floating-promises\", {\n    if: import.meta.dev,\n    otherwise: \"deny\",\n    reason: \"debug telemetry\",\n})\nmodule {}\n"
    },
    "expressions/module": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Module blocks attach typed metadata to the current source module.</span>\n<span data-k=\"comment\">* Global blocks make selected language items visible without dynamic imports.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Clone</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Debug</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:decorator&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">HtmlTree</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:ui/html&quot;</span><span data-k=\"punct\">;</span>\n\n@<span data-k=\"name\">noHeap</span>\nmodule <span data-k=\"punct\">{</span>\n    <span data-k=\"comment\">// metadata is statically visible through import.meta</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">tree</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">HtmlTree</span><span data-k=\"punct\">;</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">derive</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">Debug</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Clone</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">role</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;server&quot;</span><span data-k=\"punct\">;</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">labels</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">feature</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"string\">&quot;registry&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;documents&quot;</span><span data-k=\"punct\">]</span><span data-k=\"punct\">,</span>\n    <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nglobal <span data-k=\"punct\">{</span>\n    <span data-k=\"comment\">// selected globals enter the active module set</span>\n    <span data-k=\"keyword\">export</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Add</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Subtract</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:ops&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">role</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;server&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">tree</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">TreeTagBuilder</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Module blocks attach typed metadata to the current source module.\n* Global blocks make selected language items visible without dynamic imports.\n*/\n\nimport { Clone, Debug } from \"destack:decorator\";\nimport { HtmlTree } from \"destack:ui/html\";\n\n@noHeap\nmodule {\n    // metadata is statically visible through import.meta\n    const tree = HtmlTree;\n    const derive = [Debug, Clone];\n    const role = \"server\";\n    const labels = {\n        feature: [\"registry\", \"documents\"],\n    };\n}\n\nglobal {\n    // selected globals enter the active module set\n    export { Add, Subtract } from \"destack:ops\";\n}\n\nimport.meta.role satisfies \"server\";\nimport.meta.tree satisfies TreeTagBuilder;\n"
    },
    "expressions/comptime": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Destack supports a `comptime` execution environment.</span>\n<span data-k=\"comment\">* `comptime` modifier / expression evaluates during compilation.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">assert</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:assert&quot;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// this function can run at compile time or runtime</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">crc</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint8</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">value</span><span data-k=\"punct\">.</span><span data-k=\"name\">reverseBits</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// comptime expressions return ordinary values</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"type\">CRC_TABLE</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> comptime <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">let</span> <span data-k=\"name\">table</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n    <span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">let</span> <span data-k=\"name\">i</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span> <span data-k=\"name\">i</span> <span data-k=\"punct\">&lt;</span> <span data-k=\"literal\">256</span><span data-k=\"punct\">;</span> <span data-k=\"name\">i</span><span data-k=\"punct\">++</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">table</span><span data-k=\"punct\">.</span><span data-k=\"name\">push</span><span data-k=\"punct\">(</span><span data-k=\"name\">crc</span><span data-k=\"punct\">(</span><span data-k=\"name\">i</span> <span data-k=\"keyword\">as</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n    <span data-k=\"name\">table</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// comptime blocks can validate generic values</span>\nstruct <span data-k=\"type\">Buffer</span><span data-k=\"punct\">&lt;</span>comptime <span data-k=\"type\">Size</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    comptime <span data-k=\"punct\">{</span>\n        assert<span data-k=\"punct\">(</span><span data-k=\"type\">Size</span> <span data-k=\"punct\">&gt;</span> <span data-k=\"literal\">0</span> <span data-k=\"punct\">&amp;&amp;</span> <span data-k=\"type\">Size</span> <span data-k=\"punct\">&lt;=</span> <span data-k=\"literal\">65536</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n\n    <span data-k=\"name\">data</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"type\">Size</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Destack supports a `comptime` execution environment.\n* `comptime` modifier / expression evaluates during compilation.\n*/\n\nimport { assert } from \"destack:assert\";\n\n// this function can run at compile time or runtime\nfunction crc(value: uint8): uint8 {\n    value.reverseBits()\n}\n\n// comptime expressions return ordinary values\nconst CRC_TABLE: uint8[] = comptime {\n    let table: uint8[] = [];\n    for (let i = 0; i < 256; i++) {\n        table.push(crc(i as uint8));\n    }\n    table\n};\n\n// comptime blocks can validate generic values\nstruct Buffer<comptime Size: uint> {\n    comptime {\n        assert(Size > 0 && Size <= 65536);\n    }\n\n    data: [uint8; Size];\n}\n"
    },
    "expressions/macros": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Macros are decorators backed by bounded comptime module editing.</span>\n<span data-k=\"comment\">* Expansion runs recursively until no macro work remains.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">FunctionDeclaration</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Macro</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:macro&quot;</span><span data-k=\"punct\">;</span>\n\nnewtype <span data-k=\"type\">UserId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span>\n\nnewtype <span data-k=\"type\">memoize</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">capacity</span><span data-k=\"punct\">?</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">LoadError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">MemoizeState</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">innerName</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">readUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">LoadError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// macro decorators are just typed values</span>\n@<span data-k=\"name\">memoize</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span> <span data-k=\"name\">capacity</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1024</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">load</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">LoadError</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">readUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// expansion receives the target and bounded edit context</span>\nextension <span data-k=\"keyword\">of</span> <span data-k=\"type\">memoize</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">Macro</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">FunctionDeclaration</span><span data-k=\"punct\">,</span> <span data-k=\"type\">MemoizeState</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">static</span> <span data-k=\"name\">expand</span><span data-k=\"punct\">(</span><span data-k=\"name\">target</span><span data-k=\"punct\">,</span> <span data-k=\"name\">context</span><span data-k=\"punct\">,</span> <span data-k=\"name\">config</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">MemoizeState</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"keyword\">const</span> <span data-k=\"name\">innerName</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">`${context.name}Inner`</span><span data-k=\"punct\">;</span>\n        <span data-k=\"name\">context</span><span data-k=\"punct\">.</span><span data-k=\"name\">renameTarget</span><span data-k=\"punct\">(</span><span data-k=\"name\">innerName</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n        <span data-k=\"name\">context</span><span data-k=\"punct\">.</span><span data-k=\"name\">add</span><span data-k=\"punct\">(</span><span data-k=\"name\">renderWrapper</span><span data-k=\"punct\">(</span><span data-k=\"name\">context</span><span data-k=\"punct\">.</span><span data-k=\"name\">name</span><span data-k=\"punct\">,</span> <span data-k=\"name\">innerName</span><span data-k=\"punct\">,</span> <span data-k=\"name\">config</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n        <span data-k=\"keyword\">return</span> <span data-k=\"type\">MemoizeState</span> <span data-k=\"punct\">{</span> innerName <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// generated code is rendered as a virtual `.ds` source file</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">renderWrapper</span><span data-k=\"punct\">(</span><span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"name\">innerName</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"name\">config</span><span data-k=\"punct\">:</span> <span data-k=\"type\">memoize</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">capacity</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">config</span><span data-k=\"punct\">.</span><span data-k=\"name\">capacity</span> <span data-k=\"punct\">??</span> <span data-k=\"literal\">256</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"keyword\">return</span> <span data-k=\"string\">`</span>\n<span data-k=\"string\">        const ${name}Cache = new LruCache&lt;UserId, Result&lt;User, LoadError&gt;&gt;(${capacity});</span>\n<span data-k=\"string\"></span>\n<span data-k=\"string\">        function ${name}(id: UserId): Result&lt;User, LoadError&gt; {</span>\n<span data-k=\"string\">            if (${name}Cache.has(id)) {</span>\n<span data-k=\"string\">                return ${name}Cache.get(id)!;</span>\n<span data-k=\"string\">            }</span>\n<span data-k=\"string\"></span>\n<span data-k=\"string\">            const value = ${innerName}(id);</span>\n<span data-k=\"string\">            ${name}Cache.set(id, value);</span>\n<span data-k=\"string\">            return value;</span>\n<span data-k=\"string\">        }</span>\n<span data-k=\"string\">    `</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Macros are decorators backed by bounded comptime module editing.\n* Expansion runs recursively until no macro work remains.\n*/\n\nimport { Result } from \"destack:error\";\nimport { FunctionDeclaration, Macro } from \"destack:macro\";\n\nnewtype UserId = uint64;\n\nnewtype memoize = {\n    capacity?: uint;\n};\n\nstruct User {\n    id: UserId;\n    name: string;\n}\n\nstruct LoadError {\n    message: string;\n}\n\nstruct MemoizeState {\n    innerName: string;\n}\n\ndeclare function readUser(id: UserId): Result<User, LoadError>;\n\n// macro decorators are just typed values\n@memoize({ capacity: 1024 })\nfunction load(id: UserId): Result<User, LoadError> {\n    readUser(id)\n}\n\n// expansion receives the target and bounded edit context\nextension of memoize implements Macro<FunctionDeclaration, MemoizeState> {\n    static expand(target, context, config): MemoizeState {\n        const innerName = `${context.name}Inner`;\n        context.renameTarget(innerName);\n        context.add(renderWrapper(context.name, innerName, config));\n\n        return MemoizeState { innerName };\n    }\n}\n\n// generated code is rendered as a virtual `.ds` source file\nfunction renderWrapper(name: string, innerName: string, config: memoize): string {\n    const capacity = config.capacity ?? 256;\n\n    return `\n        const ${name}Cache = new LruCache<UserId, Result<User, LoadError>>(${capacity});\n\n        function ${name}(id: UserId): Result<User, LoadError> {\n            if (${name}Cache.has(id)) {\n                return ${name}Cache.get(id)!;\n            }\n\n            const value = ${innerName}(id);\n            ${name}Cache.set(id, value);\n            return value;\n        }\n    `;\n}\n"
    },
    "expressions/captures": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Regular closures capture the surrounding lexical environment.</span>\n<span data-k=\"comment\">* Capture decorators expose copy, borrow, and move control when needed.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"comment\">// regular lexical capture of 'count' in a managed frame</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">count</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">0</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">next</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">count</span> <span data-k=\"punct\">+=</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">count</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// copy count into the snapshot capture (by value)</span>\n@<span data-k=\"name\">capture</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;copy&quot;</span><span data-k=\"punct\">)</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">snapshot</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">count</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// borrow count from the containing frame</span>\n@<span data-k=\"name\">capture</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;borrow&quot;</span><span data-k=\"punct\">)</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">borrowed</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Function</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">,</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">count</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// move count into the closure by value</span>\n@<span data-k=\"name\">capture</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;move&quot;</span><span data-k=\"punct\">)</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">owned</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Function</span><span data-k=\"punct\">&lt;</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">,</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">count</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Regular closures capture the surrounding lexical environment.\n* Capture decorators expose copy, borrow, and move control when needed.\n*/\n\n// regular lexical capture of 'count' in a managed frame\nlet count = 0;\nconst next = () => {\n    count += 1;\n    count\n};\n\n// copy count into the snapshot capture (by value)\n@capture(\"copy\")\nconst snapshot = () => count;\n\n// borrow count from the containing frame\n@capture(\"borrow\")\nconst borrowed: &Function<(), int32> = () => count;\n\n// move count into the closure by value\n@capture(\"move\")\nconst owned: ^Function<(), int32> = () => count;\n"
    },
    "memory/space": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Placement decides where values live.</span>\n<span data-k=\"comment\">* `shared` is memory placement, not synchronization.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">Header</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">traceId</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">JsonBody</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">text</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">class</span> <span data-k=\"type\">World</span> <span data-k=\"punct\">{</span><span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Body</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">header</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Header</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">body</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Body</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// ordinary managed values live in local worker memory</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">localRequest</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">JsonBody</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// shared values are visible to workers in the same runtime</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">sharedRequest</span><span data-k=\"punct\">:</span> shared <span data-k=\"type\">Request</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">JsonBody</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\nshared <span data-k=\"keyword\">const</span> <span data-k=\"name\">world</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">World</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">RegistryStats</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">reads</span><span data-k=\"punct\">:</span> <span data-k=\"type\">AtomicU64</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">writes</span><span data-k=\"punct\">:</span> <span data-k=\"type\">AtomicU64</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nshared <span data-k=\"keyword\">const</span> <span data-k=\"name\">stats</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">RegistryStats</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">reads</span><span data-k=\"punct\">:</span> <span data-k=\"type\">AtomicU64</span><span data-k=\"punct\">(</span><span data-k=\"literal\">0</span><span data-k=\"punct\">)</span><span data-k=\"punct\">,</span>\n    <span data-k=\"name\">writes</span><span data-k=\"punct\">:</span> <span data-k=\"type\">AtomicU64</span><span data-k=\"punct\">(</span><span data-k=\"literal\">0</span><span data-k=\"punct\">)</span><span data-k=\"punct\">,</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// synchronization still comes from explicit atomic fields</span>\n<span data-k=\"name\">stats</span><span data-k=\"punct\">.</span><span data-k=\"name\">reads</span><span data-k=\"punct\">.</span><span data-k=\"name\">add</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Placement decides where values live.\n* `shared` is memory placement, not synchronization.\n*/\n\nstruct Header {\n    traceId: string;\n}\n\nstruct JsonBody {\n    text: string;\n}\n\nclass World {}\n\nstruct Request<Body> {\n    header: Header;\n    body: Body;\n}\n\n// ordinary managed values live in local worker memory\nlet localRequest: Request<JsonBody>;\n\n// shared values are visible to workers in the same runtime\nlet sharedRequest: shared Request<JsonBody>;\n\nshared const world = new World();\n\nstruct RegistryStats {\n    reads: AtomicU64;\n    writes: AtomicU64;\n}\n\nshared const stats = RegistryStats {\n    reads: AtomicU64(0),\n    writes: AtomicU64(0),\n};\n\n// synchronization still comes from explicit atomic fields\nstats.reads.add(1);\n"
    },
    "memory/ownership": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Ownership decides who keeps a value alive and when it is freed.</span>\n<span data-k=\"comment\">* Managed values are the default, explicit owners use `^T`.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">class</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// managed is default, owned is explicit</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">managed</span><span data-k=\"punct\">:</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">owned</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// borrows choose their access mode</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">borrowed</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">managed</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">readonlyBorrow</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">managed</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">ownedBorrow</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"name\">owned</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">raw</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">managed</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// access controls mutation through the reference</span>\n<span data-k=\"name\">borrowed</span><span data-k=\"punct\">.</span><span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;Ada&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">readonlyBorrow</span><span data-k=\"punct\">.</span><span data-k=\"name\">name</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">ownedBorrow</span><span data-k=\"punct\">.</span><span data-k=\"name\">name</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;Grace&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">raw</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Ownership decides who keeps a value alive and when it is freed.\n* Managed values are the default, explicit owners use `^T`.\n*/\n\nclass User {\n    name: string = \"\";\n}\n\n// managed is default, owned is explicit\nlet managed: User = new User();\nlet owned: ^User = new User();\n\n// borrows choose their access mode\nlet borrowed: &User = &managed;\nlet readonlyBorrow: &readonly User = &readonly managed;\nlet ownedBorrow: &exclusive User = &exclusive owned;\nlet raw: *User = &managed;\n\n// access controls mutation through the reference\nborrowed.name = \"Ada\";\nreadonlyBorrow.name satisfies string;\nownedBorrow.name = \"Grace\";\nraw satisfies *User;\n"
    },
    "memory/borrowing": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Borrowing keeps references valid while their source remains alive.</span>\n<span data-k=\"comment\">* Exclusive borrows cannot overlap with any live borrow of the same path.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">point</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">1</span><span data-k=\"punct\">,</span> <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">2</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// disjoint fields can be borrowed at the same time</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">readX</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">point</span><span data-k=\"punct\">.</span><span data-k=\"name\">x</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">writeY</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">point</span><span data-k=\"punct\">.</span><span data-k=\"name\">y</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"punct\">*</span><span data-k=\"name\">writeY</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">3</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">readX</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// exclusive access conflicts with the live readonly borrow</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">exclusiveX</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"name\">point</span><span data-k=\"punct\">.</span><span data-k=\"name\">x</span><span data-k=\"punct\">;</span>\n                 <span data-k=\"inline-diagnostic-shadow\"><span data-k=\"inline-diagnostic-box\"><span data-k=\"squiggle\">~~~~~~~~~~~~~~~~~~</span>\n<span data-k=\"message\">error: overlaps live readonly borrow readX</span></span></span>\n\n<span data-k=\"punct\">*</span><span data-k=\"name\">exclusiveX</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">4</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// full exclusive access is required for invalidating operations</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">translate</span><span data-k=\"punct\">(</span><span data-k=\"name\">point</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"type\">Point</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">translate</span><span data-k=\"punct\">(</span><span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"name\">point</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Borrowing keeps references valid while their source remains alive.\n* Exclusive borrows cannot overlap with any live borrow of the same path.\n*/\n\nstruct Point {\n    x: int32;\n    y: int32;\n}\n\nlet point = ^Point { x: 1, y: 2 };\n\n// disjoint fields can be borrowed at the same time\nlet readX = &readonly point.x;\nlet writeY = &point.y;\n\n*writeY = 3;\nreadX satisfies &readonly int32;\n\n// exclusive access conflicts with the live readonly borrow\nlet exclusiveX = &exclusive point.x;\n                 ~~~~~~~~~~~~~~~~~~\n                 error: overlaps live readonly borrow readX\n\n*exclusiveX = 4;\n\n// full exclusive access is required for invalidating operations\ndeclare function translate(point: &exclusive Point): void;\ntranslate(&exclusive point);\n"
    },
    "memory/lifetimes": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Lifetimes describe the relationship between owners and borrowed access.</span>\n<span data-k=\"comment\">* Inference joins the lifetimes of all possible returned branches.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">Node</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">parent</span><span data-k=\"punct\">?</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// returned borrows inherit the input lifetime</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">first</span><span data-k=\"punct\">(</span><span data-k=\"name\">left</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"name\">right</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">left</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// branch joins preserve the live owner relation</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">choose</span><span data-k=\"punct\">(</span><span data-k=\"name\">left</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"name\">right</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"name\">useLeft</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"name\">useLeft</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">left</span>\n    <span data-k=\"punct\">}</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">right</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// nested access can borrow from the selected node</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">selectedName</span><span data-k=\"punct\">(</span><span data-k=\"name\">left</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"name\">right</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">Node</span><span data-k=\"punct\">,</span> <span data-k=\"name\">useLeft</span><span data-k=\"punct\">:</span> <span data-k=\"type\">boolean</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">string</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"punct\">&amp;</span><span data-k=\"name\">choose</span><span data-k=\"punct\">(</span><span data-k=\"name\">left</span><span data-k=\"punct\">,</span> <span data-k=\"name\">right</span><span data-k=\"punct\">,</span> <span data-k=\"name\">useLeft</span><span data-k=\"punct\">)</span><span data-k=\"punct\">.</span><span data-k=\"name\">name</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Lifetimes describe the relationship between owners and borrowed access.\n* Inference joins the lifetimes of all possible returned branches.\n*/\n\nstruct Node {\n    name: string;\n    parent?: &Node;\n}\n\n// returned borrows inherit the input lifetime\nfunction first(left: &Node, right: &Node): &Node {\n    left\n}\n\n// branch joins preserve the live owner relation\nfunction choose(left: &Node, right: &Node, useLeft: boolean): &Node {\n    if (useLeft) {\n        left\n    } else {\n        right\n    }\n}\n\n// nested access can borrow from the selected node\nfunction selectedName(left: &Node, right: &Node, useLeft: boolean): &string {\n    &choose(left, right, useLeft).name\n}\n"
    },
    "memory/drop": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Drop follows ownership lifetime, not lexical scope.</span>\n<span data-k=\"comment\">* It is for memory-shaped finalization and owned fields.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Drop</span><span data-k=\"punct\">,</span> <span data-k=\"type\">ManuallyDrop</span><span data-k=\"punct\">,</span> <span data-k=\"name\">drop</span><span data-k=\"punct\">,</span> <span data-k=\"name\">forget</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:memory&quot;</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">Buffer</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">Drop</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">length</span><span data-k=\"punct\">:</span> <span data-k=\"type\">usize</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"comment\">// release owned allocation storage</span>\n    <span data-k=\"name\">drop</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">free</span><span data-k=\"punct\">(</span><span data-k=\"name\">pointer</span><span data-k=\"punct\">,</span> <span data-k=\"name\">length</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">allocate</span><span data-k=\"punct\">(</span><span data-k=\"name\">length</span><span data-k=\"punct\">:</span> <span data-k=\"type\">usize</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">^</span><span data-k=\"type\">Buffer</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">free</span><span data-k=\"punct\">(</span><span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">,</span> <span data-k=\"name\">length</span><span data-k=\"punct\">:</span> <span data-k=\"type\">usize</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">process</span><span data-k=\"punct\">(</span><span data-k=\"name\">buffer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">Buffer</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">run</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">let</span> <span data-k=\"name\">buffer</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">allocate</span><span data-k=\"punct\">(</span><span data-k=\"literal\">4096</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">process</span><span data-k=\"punct\">(</span><span data-k=\"punct\">&amp;</span><span data-k=\"name\">buffer</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"comment\">// ownership can end before scope exit</span>\n    <span data-k=\"name\">drop</span><span data-k=\"punct\">(</span><span data-k=\"name\">buffer</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// low-level code can suppress automatic drop</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">staged</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">ManuallyDrop</span><span data-k=\"punct\">.</span><span data-k=\"name\">new</span><span data-k=\"punct\">(</span><span data-k=\"name\">allocate</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1024</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">leaked</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">staged</span><span data-k=\"punct\">.</span><span data-k=\"name\">intoInner</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">forget</span><span data-k=\"punct\">(</span><span data-k=\"name\">leaked</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Drop follows ownership lifetime, not lexical scope.\n* It is for memory-shaped finalization and owned fields.\n*/\n\nimport { Drop, ManuallyDrop, drop, forget } from \"destack:memory\";\n\nstruct Buffer implements Drop {\n    pointer: *uint8;\n    length: usize;\n\n    // release owned allocation storage\n    drop(): void {\n        free(pointer, length);\n    }\n}\n\ndeclare function allocate(length: usize): ^Buffer;\ndeclare function free(pointer: *uint8, length: usize): void;\ndeclare function process(buffer: &readonly Buffer): void;\n\nfunction run(): void {\n    let buffer = allocate(4096);\n    process(&buffer);\n\n    // ownership can end before scope exit\n    drop(buffer);\n}\n\n// low-level code can suppress automatic drop\nlet staged = ManuallyDrop.new(allocate(1024));\nlet leaked = staged.intoInner();\n\nforget(leaked);\n"
    },
    "memory/dispose": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Dispose and AsyncDispose are lexical resource cleanup protocols.</span>\n<span data-k=\"comment\">* `using` runs cleanup on every exit path, including `?`.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Promise</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:async&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">AsyncDispose</span><span data-k=\"punct\">,</span> <span data-k=\"type\">Dispose</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:memory&quot;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">class</span> <span data-k=\"type\">FileHandle</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">Dispose</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">descriptor</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"comment\">// close the host resource at scope exit</span>\n    <span data-k=\"name\">dispose</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">close</span><span data-k=\"punct\">(</span><span data-k=\"name\">descriptor</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">class</span> <span data-k=\"type\">Connection</span> <span data-k=\"keyword\">implements</span> <span data-k=\"type\">AsyncDispose</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"comment\">// wait for the remote close handshake</span>\n    <span data-k=\"name\">asyncDispose</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">flushAndClose</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">open</span><span data-k=\"punct\">(</span><span data-k=\"name\">path</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">FileHandle</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">close</span><span data-k=\"punct\">(</span><span data-k=\"name\">descriptor</span><span data-k=\"punct\">:</span> <span data-k=\"type\">int32</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">void</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">flushAndClose</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Promise</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">copy</span><span data-k=\"punct\">(</span><span data-k=\"name\">input</span><span data-k=\"punct\">:</span> <span data-k=\"type\">FileHandle</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">copyFile</span><span data-k=\"punct\">(</span><span data-k=\"name\">path</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    using <span data-k=\"name\">file</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">open</span><span data-k=\"punct\">(</span><span data-k=\"name\">path</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">copy</span><span data-k=\"punct\">(</span><span data-k=\"name\">file</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Dispose and AsyncDispose are lexical resource cleanup protocols.\n* `using` runs cleanup on every exit path, including `?`.\n*/\n\nimport { Promise } from \"destack:async\";\nimport { Result } from \"destack:error\";\nimport { AsyncDispose, Dispose } from \"destack:memory\";\n\nclass FileHandle implements Dispose {\n    descriptor: int32;\n\n    // close the host resource at scope exit\n    dispose(): void {\n        close(descriptor);\n    }\n}\n\nclass Connection implements AsyncDispose {\n    // wait for the remote close handshake\n    asyncDispose(): Promise<void> {\n        flushAndClose()\n    }\n}\n\ndeclare function open(path: string): Result<FileHandle, IOError>;\ndeclare function close(descriptor: int32): void;\ndeclare function flushAndClose(): Promise<void>;\ndeclare function copy(input: FileHandle): Result<void, IOError>;\n\nfunction copyFile(path: string): Result<void, IOError> {\n    using file = open(path)?;\n\n    copy(file)\n}\n"
    },
    "memory/unsafe": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Safe code can create and carry raw pointers.</span>\n<span data-k=\"comment\">* Unsafe code is required only for operations that may violate invariants.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">class</span> <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">new</span> <span data-k=\"type\">User</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// converting a borrow to a pointer is safe</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">borrow</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">&amp;</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">&amp;</span><span data-k=\"name\">user</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">borrow</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">let</span> <span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">uint8</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">pointer</span> <span data-k=\"keyword\">as</span> <span data-k=\"punct\">*</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"name\">pointer</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">bytes</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">*</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// dereferencing raw memory requires an unsafe boundary</span>\n@<span data-k=\"name\">unsafe</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">readName</span><span data-k=\"punct\">(</span><span data-k=\"name\">pointer</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">*</span><span data-k=\"type\">User</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">user</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">asReference</span><span data-k=\"punct\">(</span><span data-k=\"name\">pointer</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">user</span><span data-k=\"punct\">.</span><span data-k=\"name\">name</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// safe wrappers must restore the invariant</span>\n@<span data-k=\"name\">safe</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">get</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">(</span><span data-k=\"name\">items</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Slice</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">T</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">,</span> <span data-k=\"name\">index</span><span data-k=\"punct\">:</span> <span data-k=\"type\">usize</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">T</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">items</span><span data-k=\"punct\">.</span><span data-k=\"name\">unsafeGet</span><span data-k=\"punct\">(</span><span data-k=\"name\">index</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Safe code can create and carry raw pointers.\n* Unsafe code is required only for operations that may violate invariants.\n*/\n\nclass User {\n    name: string = \"\";\n}\n\nlet user = new User();\n\n// converting a borrow to a pointer is safe\nlet borrow: &User = &user;\nlet pointer: *User = borrow;\nlet bytes: *uint8 = pointer as *uint8;\n\npointer satisfies *User;\nbytes satisfies *uint8;\n\n// dereferencing raw memory requires an unsafe boundary\n@unsafe\nfunction readName(pointer: *User): string {\n    const user = asReference(pointer);\n    user.name\n}\n\n// safe wrappers must restore the invariant\n@safe\nfunction get<T>(items: Slice<T>, index: usize): T {\n    items.unsafeGet(index)\n}\n"
    },
    "memory/polymorphism": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Generic code can dispatch on the selected memory form.</span>\n<span data-k=\"comment\">* Iteration preserves access and ownership in the yielded value.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">Point</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">x</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">y</span><span data-k=\"punct\">:</span> <span data-k=\"type\">number</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">const</span> <span data-k=\"name\">points</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// default iteration yields ordinary values</span>\n<span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// readonly iteration preserves readonly access</span>\n<span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span><span data-k=\"keyword\">readonly</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// exclusive iteration permits mutation of each item</span>\n<span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"punct\">&amp;</span>exclusive <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// owned iteration consumes the owner</span>\n<span data-k=\"keyword\">for</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">const</span> <span data-k=\"name\">point</span> <span data-k=\"keyword\">of</span> <span data-k=\"punct\">^</span><span data-k=\"name\">points</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">point</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Point</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n",
        "source": "/**\n* Generic code can dispatch on the selected memory form.\n* Iteration preserves access and ownership in the yielded value.\n*/\n\nstruct Point {\n    x: number;\n    y: number;\n}\n\ndeclare const points: Point[];\n\n// default iteration yields ordinary values\nfor (const point of points) {\n    point satisfies Point;\n}\n\n// readonly iteration preserves readonly access\nfor (const point of &readonly points) {\n    point satisfies &readonly Point;\n}\n\n// exclusive iteration permits mutation of each item\nfor (const point of &exclusive points) {\n    point satisfies &exclusive Point;\n}\n\n// owned iteration consumes the owner\nfor (const point of ^points) {\n    point satisfies Point;\n}\n"
    },
    "runtime/modules": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Runtime modules carry typed metadata and a static source graph.</span>\n<span data-k=\"comment\">* `import.meta` exposes the module metadata to checked code.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n\nnewtype <span data-k=\"type\">UserId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">User</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">LoadError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nmodule <span data-k=\"punct\">{</span>\n    <span data-k=\"comment\">// metadata is part of the module graph</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">role</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;server&quot;</span><span data-k=\"punct\">;</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">labels</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">feature</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"string\">&quot;registry&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;documents&quot;</span><span data-k=\"punct\">]</span><span data-k=\"punct\">,</span>\n    <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">readUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">LoadError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// exports remain ordinary static module exports</span>\n<span data-k=\"keyword\">export</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">loadUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">UserId</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">User</span><span data-k=\"punct\">,</span> <span data-k=\"type\">LoadError</span><span data-k=\"punct\">&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">readUser</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// metadata fields are typed by the module block</span>\n<span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">role</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;server&quot;</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Runtime modules carry typed metadata and a static source graph.\n* `import.meta` exposes the module metadata to checked code.\n*/\n\nimport { Result } from \"destack:error\";\n\nnewtype UserId = uint64;\n\nstruct User {\n    id: UserId;\n    name: string;\n}\n\nstruct LoadError {\n    message: string;\n}\n\nmodule {\n    // metadata is part of the module graph\n    const role = \"server\";\n    const labels = {\n        feature: [\"registry\", \"documents\"],\n    };\n}\n\ndeclare function readUser(id: UserId): Result<User, LoadError>;\n\n// exports remain ordinary static module exports\nexport function loadUser(id: UserId): Result<User, LoadError> {\n    readUser(id)\n}\n\n// metadata fields are typed by the module block\nimport.meta.role satisfies \"server\";\n"
    },
    "runtime/conditions": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Conditions gate sources, dependencies, and code paths.</span>\n<span data-k=\"comment\">* Condition aliases compose through the module graph and target config.</span>\n<span data-k=\"comment\">*/</span>\n\nstruct <span data-k=\"type\">Renderer</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">Transport</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">protocol</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">newRenderer</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Renderer</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">oldRenderer</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Renderer</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">browserTransport</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Transport</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">nativeTransport</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Transport</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// feature gates can select implementations</span>\n<span data-k=\"keyword\">function</span> <span data-k=\"name\">renderer</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Renderer</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">features</span><span data-k=\"punct\">.</span><span data-k=\"name\">includes</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;rendererv2&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">newRenderer</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span>\n    <span data-k=\"punct\">}</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">oldRenderer</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span>\n    <span data-k=\"punct\">}</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// host gates can select platform integrations</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">transport</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">if</span> <span data-k=\"punct\">(</span><span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">host</span> <span data-k=\"punct\">==</span> <span data-k=\"string\">&quot;browser&quot;</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">browserTransport</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span> <span data-k=\"keyword\">else</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">nativeTransport</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Conditions gate sources, dependencies, and code paths.\n* Condition aliases compose through the module graph and target config.\n*/\n\nstruct Renderer {\n    name: string;\n}\n\nstruct Transport {\n    protocol: string;\n}\n\ndeclare function newRenderer(): Renderer;\ndeclare function oldRenderer(): Renderer;\ndeclare function browserTransport(): Transport;\ndeclare function nativeTransport(): Transport;\n\n// feature gates can select implementations\nfunction renderer(): Renderer {\n    if (import.meta.features.includes(\"rendererv2\")) {\n        newRenderer()\n    } else {\n        oldRenderer()\n    }\n}\n\n// host gates can select platform integrations\nconst transport = if (import.meta.host == \"browser\") {\n    browserTransport()\n} else {\n    nativeTransport()\n};\n"
    },
    "runtime/import-meta": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* `import.meta` exposes target, mode, runtime, and module metadata.</span>\n<span data-k=\"comment\">* The fields are typed by the active compiler configuration.</span>\n<span data-k=\"comment\">*/</span>\n\nmodule <span data-k=\"punct\">{</span>\n    <span data-k=\"comment\">// custom metadata joins builtin fields</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">product</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;studio&quot;</span><span data-k=\"punct\">;</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">labels</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">feature</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"string\">&quot;editor&quot;</span><span data-k=\"punct\">]</span><span data-k=\"punct\">,</span>\n    <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// builtin fields describe the active target</span>\n<span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">url</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">platform</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Platform</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">host</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Host</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">runtime</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Runtime</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">modes</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">Mode</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">features</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"type\">Feature</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">product</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"string\">&quot;studio&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">labels</span><span data-k=\"punct\">.</span><span data-k=\"name\">feature</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"keyword\">readonly</span> <span data-k=\"punct\">[</span><span data-k=\"string\">&quot;editor&quot;</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// convenience flags stay derived from modes</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">debug</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">dev</span> <span data-k=\"punct\">||</span> <span data-k=\"keyword\">import</span><span data-k=\"punct\">.</span>meta<span data-k=\"punct\">.</span><span data-k=\"name\">test</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* `import.meta` exposes target, mode, runtime, and module metadata.\n* The fields are typed by the active compiler configuration.\n*/\n\nmodule {\n    // custom metadata joins builtin fields\n    const product = \"studio\";\n    const labels = {\n        feature: [\"editor\"],\n    };\n}\n\n// builtin fields describe the active target\nimport.meta.url satisfies string;\nimport.meta.platform satisfies Platform;\nimport.meta.host satisfies Host;\nimport.meta.runtime satisfies Runtime;\nimport.meta.modes satisfies readonly Mode[];\nimport.meta.features satisfies readonly Feature[];\nimport.meta.product satisfies \"studio\";\nimport.meta.labels.feature satisfies readonly [\"editor\"];\n\n// convenience flags stay derived from modes\nconst debug = import.meta.dev || import.meta.test;\n"
    },
    "runtime/data-modules": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Data, text, and binary modules stay in the static graph.</span>\n<span data-k=\"comment\">* Import attributes select the desired module representation.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"name\">config</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;./config.json&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"name\">readme</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;./README.md&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"name\">icon</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;./icon.png&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"name\">schema</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;./schema.sql&quot;</span> <span data-k=\"keyword\">with</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">type</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;text&quot;</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"name\">wasm</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;./parser.wasm&quot;</span> <span data-k=\"keyword\">with</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">type</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;binary&quot;</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// imported data can be checked against local types</span>\nstruct <span data-k=\"type\">Config</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">server</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">{</span>\n        <span data-k=\"name\">host</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n        <span data-k=\"name\">port</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint16</span><span data-k=\"punct\">;</span>\n    <span data-k=\"punct\">}</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"comment\">// each imported module has an inferred representation</span>\n<span data-k=\"name\">config</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">Config</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">readme</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">icon</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">schema</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"name\">wasm</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">uint8</span><span data-k=\"punct\">[</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Data, text, and binary modules stay in the static graph.\n* Import attributes select the desired module representation.\n*/\n\nimport config from \"./config.json\";\nimport readme from \"./README.md\";\nimport icon from \"./icon.png\";\nimport schema from \"./schema.sql\" with { type: \"text\" };\nimport wasm from \"./parser.wasm\" with { type: \"binary\" };\n\n// imported data can be checked against local types\nstruct Config {\n    server: {\n        host: string;\n        port: uint16;\n    };\n}\n\n// each imported module has an inferred representation\nconfig satisfies Config;\nreadme satisfies string;\nicon satisfies uint8[];\nschema satisfies string;\nwasm satisfies uint8[];\n"
    },
    "runtime/policy": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Runtime policy declares host capability access for a module.</span>\n<span data-k=\"comment\">* Calls through host bindings can be checked against the policy.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n\n@<span data-k=\"name\">policy</span><span data-k=\"punct\">(</span><span data-k=\"punct\">{</span>\n    <span data-k=\"comment\">// allowed host effects stay explicit</span>\n    <span data-k=\"name\">allow</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span>\n        <span data-k=\"string\">&quot;fs.read:./public&quot;</span><span data-k=\"punct\">,</span>\n        <span data-k=\"string\">&quot;net.connect:https://api.destack.sh&quot;</span><span data-k=\"punct\">,</span>\n    <span data-k=\"punct\">]</span><span data-k=\"punct\">,</span>\n    <span data-k=\"comment\">// denied effects fail at the boundary</span>\n    <span data-k=\"name\">deny</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span>\n        <span data-k=\"string\">&quot;process.spawn&quot;</span><span data-k=\"punct\">,</span>\n    <span data-k=\"punct\">]</span><span data-k=\"punct\">,</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">)</span>\nmodule <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">role</span> <span data-k=\"punct\">=</span> <span data-k=\"string\">&quot;server&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">IOError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">readPublic</span><span data-k=\"punct\">(</span><span data-k=\"name\">path</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">spawn</span><span data-k=\"punct\">(</span><span data-k=\"name\">command</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">,</span> <span data-k=\"type\">IOError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// host calls are checked against module policy</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">text</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">readPublic</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;./public/index.html&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Runtime policy declares host capability access for a module.\n* Calls through host bindings can be checked against the policy.\n*/\n\nimport { Result } from \"destack:error\";\n\n@policy({\n    // allowed host effects stay explicit\n    allow: [\n        \"fs.read:./public\",\n        \"net.connect:https://api.destack.sh\",\n    ],\n    // denied effects fail at the boundary\n    deny: [\n        \"process.spawn\",\n    ],\n})\nmodule {\n    const role = \"server\";\n}\n\nstruct IOError {\n    message: string;\n}\n\ndeclare function readPublic(path: string): Result<string, IOError>;\ndeclare function spawn(command: string): Result<void, IOError>;\n\n// host calls are checked against module policy\nconst text = readPublic(\"./public/index.html\")?;\n"
    },
    "runtime/test": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Tests exercise typed outcomes inside the same toolchain.</span>\n<span data-k=\"comment\">* Assertions can depend on Destack types, not stringly compiler output.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">expect</span><span data-k=\"punct\">,</span> <span data-k=\"name\">test</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:test&quot;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">UserPort</span> <span data-k=\"punct\">=</span> <span data-k=\"literal\">1024</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">65535</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">ParseError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">parsePort</span><span data-k=\"punct\">(</span><span data-k=\"name\">raw</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">UserPort</span><span data-k=\"punct\">,</span> <span data-k=\"type\">ParseError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// typed results can be opened inside tests</span>\n<span data-k=\"name\">test</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;parsePort accepts user ports&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">port</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">parsePort</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;8080&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"comment\">// assertions can keep static type guarantees nearby</span>\n    <span data-k=\"name\">expect</span><span data-k=\"punct\">(</span><span data-k=\"name\">port</span><span data-k=\"punct\">)</span><span data-k=\"punct\">.</span><span data-k=\"name\">toBe</span><span data-k=\"punct\">(</span><span data-k=\"literal\">8080</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">port</span> <span data-k=\"keyword\">satisfies</span> <span data-k=\"type\">UserPort</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Tests exercise typed outcomes inside the same toolchain.\n* Assertions can depend on Destack types, not stringly compiler output.\n*/\n\nimport { Result } from \"destack:error\";\nimport { expect, test } from \"destack:test\";\n\ntype UserPort = 1024..=65535;\n\nstruct ParseError {\n    message: string;\n}\n\ndeclare function parsePort(raw: string): Result<UserPort, ParseError>;\n\n// typed results can be opened inside tests\ntest(\"parsePort accepts user ports\", () => {\n    const port = parsePort(\"8080\")?;\n\n    // assertions can keep static type guarantees nearby\n    expect(port).toBe(8080);\n    port satisfies UserPort;\n});\n"
    },
    "runtime/fuzz": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Fuzz cases combine typed generators with ordinary assertions.</span>\n<span data-k=\"comment\">* Shrinking and corpus handling stay integrated with the test runtime.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Generator</span><span data-k=\"punct\">,</span> <span data-k=\"name\">case</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:fuzz&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">expect</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:test&quot;</span><span data-k=\"punct\">;</span>\n\nnewtype <span data-k=\"type\">DocumentId</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">DecodeError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">encode</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">:</span> <span data-k=\"type\">DocumentId</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">decode</span><span data-k=\"punct\">(</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">:</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">]</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">DocumentId</span><span data-k=\"punct\">,</span> <span data-k=\"type\">DecodeError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// generators can map raw primitives into domain newtypes</span>\n<span data-k=\"keyword\">const</span> <span data-k=\"name\">ids</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">Generator</span><span data-k=\"punct\">.</span><span data-k=\"name\">uint64</span><span data-k=\"punct\">(</span><span data-k=\"literal\">1</span><span data-k=\"punct\">..=</span><span data-k=\"literal\">1000000</span><span data-k=\"punct\">)</span><span data-k=\"punct\">.</span><span data-k=\"name\">map</span><span data-k=\"punct\">(</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"type\">DocumentId</span><span data-k=\"punct\">(</span><span data-k=\"name\">value</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// each generated value checks a full roundtrip</span>\n<span data-k=\"name\">case</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;document id roundtrip&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"name\">ids</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">samples</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">10000</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">expect</span><span data-k=\"punct\">(</span><span data-k=\"name\">decode</span><span data-k=\"punct\">(</span><span data-k=\"name\">encode</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">?</span><span data-k=\"punct\">)</span><span data-k=\"punct\">.</span><span data-k=\"name\">toBe</span><span data-k=\"punct\">(</span><span data-k=\"name\">id</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Fuzz cases combine typed generators with ordinary assertions.\n* Shrinking and corpus handling stay integrated with the test runtime.\n*/\n\nimport { Result } from \"destack:error\";\nimport { Generator, case } from \"destack:fuzz\";\nimport { expect } from \"destack:test\";\n\nnewtype DocumentId = uint64;\n\nstruct DecodeError {\n    message: string;\n}\n\ndeclare function encode(id: DocumentId): [uint8];\ndeclare function decode(bytes: [uint8]): Result<DocumentId, DecodeError>;\n\n// generators can map raw primitives into domain newtypes\nconst ids = Generator.uint64(1..=1000000).map((value) => DocumentId(value));\n\n// each generated value checks a full roundtrip\ncase(\"document id roundtrip\", ids, { samples: 10000 }, (id) => {\n    expect(decode(encode(id))?).toBe(id);\n});\n"
    },
    "runtime/bench": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Bench cases measure useful work and resource units together.</span>\n<span data-k=\"comment\">* The benchmark runner receives typed results from the measured function.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">case</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:bench&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Result</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"keyword\">type</span> <span data-k=\"type\">Page</span> <span data-k=\"punct\">=</span> <span data-k=\"punct\">[</span><span data-k=\"type\">uint8</span><span data-k=\"punct\">;</span> <span data-k=\"literal\">4096</span><span data-k=\"punct\">]</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">DecodeError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">offset</span><span data-k=\"punct\">:</span> <span data-k=\"type\">uint64</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">fixture</span><span data-k=\"punct\">(</span><span data-k=\"name\">name</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Page</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">decode</span><span data-k=\"punct\">(</span><span data-k=\"name\">page</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Page</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Result</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">uint64</span><span data-k=\"punct\">,</span> <span data-k=\"type\">DecodeError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// fixtures stay outside the measured loop</span>\n<span data-k=\"name\">case</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;decode page&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">minDuration</span><span data-k=\"punct\">:</span> <span data-k=\"string\">&quot;2s&quot;</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">(</span><span data-k=\"name\">ctx</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">page</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">fixture</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;index.page&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"comment\">// iteration count and bytes feed the report</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">result</span> <span data-k=\"punct\">=</span> <span data-k=\"name\">ctx</span><span data-k=\"punct\">.</span><span data-k=\"name\">iter</span><span data-k=\"punct\">(</span><span data-k=\"punct\">(</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"name\">decode</span><span data-k=\"punct\">(</span><span data-k=\"name\">page</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"name\">ctx</span><span data-k=\"punct\">.</span><span data-k=\"name\">bytes</span><span data-k=\"punct\">(</span><span data-k=\"literal\">4096</span> <span data-k=\"punct\">*</span> <span data-k=\"name\">result</span><span data-k=\"punct\">.</span><span data-k=\"name\">iterations</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Bench cases measure useful work and resource units together.\n* The benchmark runner receives typed results from the measured function.\n*/\n\nimport { case } from \"destack:bench\";\nimport { Result } from \"destack:error\";\n\ntype Page = [uint8; 4096];\n\nstruct DecodeError {\n    offset: uint64;\n}\n\ndeclare function fixture(name: string): Page;\ndeclare function decode(page: Page): Result<uint64, DecodeError>;\n\n// fixtures stay outside the measured loop\ncase(\"decode page\", { minDuration: \"2s\" }, (ctx) => {\n    const page = fixture(\"index.page\");\n\n    // iteration count and bytes feed the report\n    const result = ctx.iter(() => decode(page));\n\n    ctx.bytes(4096 * result.iterations);\n});\n"
    },
    "runtime/simulation": {
        "html": "<span data-k=\"comment\">/**</span>\n<span data-k=\"comment\">* Simulations replay runtime faults deterministically.</span>\n<span data-k=\"comment\">* Distributed behavior can be tested against a controlled world.</span>\n<span data-k=\"comment\">*/</span>\n\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">AsyncResult</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:error&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"type\">Fault</span><span data-k=\"punct\">,</span> <span data-k=\"type\">World</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:runtime&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">case</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:simulation&quot;</span><span data-k=\"punct\">;</span>\n<span data-k=\"keyword\">import</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">expect</span> <span data-k=\"punct\">}</span> <span data-k=\"keyword\">from</span> <span data-k=\"string\">&quot;destack:test&quot;</span><span data-k=\"punct\">;</span>\n\nnewtype <span data-k=\"type\">Key</span> <span data-k=\"punct\">=</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n\nstruct <span data-k=\"type\">StoreError</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">message</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n\nstruct <span data-k=\"type\">Store</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">write</span><span data-k=\"punct\">(</span><span data-k=\"name\">key</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Key</span><span data-k=\"punct\">,</span> <span data-k=\"name\">value</span><span data-k=\"punct\">:</span> <span data-k=\"type\">string</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">AsyncResult</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">void</span><span data-k=\"punct\">,</span> <span data-k=\"type\">StoreError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">read</span><span data-k=\"punct\">(</span><span data-k=\"name\">key</span><span data-k=\"punct\">:</span> <span data-k=\"type\">Key</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">AsyncResult</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">string</span><span data-k=\"punct\">,</span> <span data-k=\"type\">StoreError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span>\n<span data-k=\"keyword\">declare</span> <span data-k=\"keyword\">function</span> <span data-k=\"name\">start</span><span data-k=\"punct\">(</span><span data-k=\"name\">world</span><span data-k=\"punct\">:</span> <span data-k=\"type\">World</span><span data-k=\"punct\">)</span><span data-k=\"punct\">:</span> <span data-k=\"type\">AsyncResult</span><span data-k=\"punct\">&lt;</span><span data-k=\"type\">Store</span><span data-k=\"punct\">,</span> <span data-k=\"type\">StoreError</span><span data-k=\"punct\">&gt;</span><span data-k=\"punct\">;</span>\n\n<span data-k=\"comment\">// the world injects deterministic runtime faults</span>\n<span data-k=\"name\">case</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;store survives stale reads&quot;</span><span data-k=\"punct\">,</span> <span data-k=\"keyword\">async</span> <span data-k=\"punct\">(</span><span data-k=\"name\">ctx</span><span data-k=\"punct\">)</span> <span data-k=\"punct\">=&gt;</span> <span data-k=\"punct\">{</span>\n    <span data-k=\"name\">ctx</span><span data-k=\"punct\">.</span><span data-k=\"name\">fault</span><span data-k=\"punct\">(</span><span data-k=\"type\">Fault</span><span data-k=\"punct\">.</span><span data-k=\"name\">StaleRead</span><span data-k=\"punct\">,</span> <span data-k=\"punct\">{</span> <span data-k=\"name\">probabilityPpm</span><span data-k=\"punct\">:</span> <span data-k=\"literal\">250000</span> <span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"keyword\">const</span> <span data-k=\"name\">store</span> <span data-k=\"punct\">=</span> <span data-k=\"keyword\">await</span><span data-k=\"punct\">?</span> <span data-k=\"name\">start</span><span data-k=\"punct\">(</span><span data-k=\"name\">ctx</span><span data-k=\"punct\">.</span><span data-k=\"name\">world</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n\n    <span data-k=\"comment\">// assertions run after the simulated schedule</span>\n    <span data-k=\"keyword\">await</span><span data-k=\"punct\">?</span> <span data-k=\"name\">store</span><span data-k=\"punct\">.</span><span data-k=\"name\">write</span><span data-k=\"punct\">(</span><span data-k=\"type\">Key</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;doc:1&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">,</span> <span data-k=\"string\">&quot;ok&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n    <span data-k=\"name\">expect</span><span data-k=\"punct\">(</span><span data-k=\"keyword\">await</span><span data-k=\"punct\">?</span> <span data-k=\"name\">store</span><span data-k=\"punct\">.</span><span data-k=\"name\">read</span><span data-k=\"punct\">(</span><span data-k=\"type\">Key</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;doc:1&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">)</span><span data-k=\"punct\">.</span><span data-k=\"name\">toBe</span><span data-k=\"punct\">(</span><span data-k=\"string\">&quot;ok&quot;</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n<span data-k=\"punct\">}</span><span data-k=\"punct\">)</span><span data-k=\"punct\">;</span>\n",
        "source": "/**\n* Simulations replay runtime faults deterministically.\n* Distributed behavior can be tested against a controlled world.\n*/\n\nimport { AsyncResult } from \"destack:error\";\nimport { Fault, World } from \"destack:runtime\";\nimport { case } from \"destack:simulation\";\nimport { expect } from \"destack:test\";\n\nnewtype Key = string;\n\nstruct StoreError {\n    message: string;\n}\n\nstruct Store {\n    write(key: Key, value: string): AsyncResult<void, StoreError>;\n    read(key: Key): AsyncResult<string, StoreError>;\n}\ndeclare function start(world: World): AsyncResult<Store, StoreError>;\n\n// the world injects deterministic runtime faults\ncase(\"store survives stale reads\", async (ctx) => {\n    ctx.fault(Fault.StaleRead, { probabilityPpm: 250000 });\n    const store = await? start(ctx.world);\n\n    // assertions run after the simulated schedule\n    await? store.write(Key(\"doc:1\"), \"ok\");\n    expect(await? store.read(Key(\"doc:1\"))).toBe(\"ok\");\n});\n"
    }
} as const;
